import React, { useMemo, useState } from 'react';
import { ITEM_STATUS } from '@common/domain/liveSale/items';
import { getPriceForBidder, showAmountInCurrency } from '@common/domain/liveSale/pricing';
import { SALE_STATUS } from '@common/domain/liveSale/saleModel';
import {
  bidderConfig,
  fetchSales,
  loadSetup,
  loginAdmin,
  saveSetup,
  startSession,
} from './api';
import BidderCard from './components/BidderCard';
import useSharedSale from './hooks/useSharedSale';

export default function App() {
  const [setup, setSetup] = useState(() => loadSetup());
  const [adminToken, setAdminToken] = useState('');
  const [sales, setSales] = useState([]);
  const [session, setSession] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');

  const onChange = (field) => (e) => {
    setSetup((s) => ({ ...s, [field]: e.target.value }));
  };

  const connect = async (e) => {
    e.preventDefault();
    setBusy(true);
    setError('');
    saveSetup(setup);
    const login = await loginAdmin(setup);
    if (!login.ok) {
      setBusy(false);
      setError(login.error || 'Login failed');
      return;
    }
    setAdminToken(login.accessToken);
    const listed = await fetchSales({
      backendUrl: setup.backendUrl,
      accessToken: login.accessToken,
      search,
    });
    setBusy(false);
    if (!listed.ok) {
      setError(listed.error || 'Could not list sales');
      return;
    }
    setSales(listed.sales || []);
  };

  const refreshSales = async () => {
    if (!adminToken) {
      return;
    }
    const listed = await fetchSales({
      backendUrl: setup.backendUrl,
      accessToken: adminToken,
      search,
    });
    if (listed.ok) {
      setSales(listed.sales || []);
    }
  };

  const begin = async (e) => {
    e.preventDefault();
    if (!setup.saleUuid && !setup.saleNid) {
      setError('Pick a sale');
      return;
    }
    setBusy(true);
    setError('');
    const res = await startSession({
      backendUrl: setup.backendUrl,
      accessToken: adminToken,
      saleUuid: setup.saleUuid,
      saleNid: setup.saleNid,
      count: Number(setup.count) || 4,
    });
    setBusy(false);
    if (!res.ok) {
      setError(res.error || 'Session failed');
      return;
    }
    setSession(res);
  };

  if (session) {
    return (
      <SimScreen
        setup={setup}
        session={session}
        onExit={() => setSession(null)}
      />
    );
  }

  const liveSales = sales.filter((s) => s.status === SALE_STATUS.LIVE_AUCTION_OPEN || s.benchable);

  return (
    <div className="page">
      <h1>Bidder simulator</h1>
      <p className="muted">
        Log in as a clerk/admin, pick a live sale, choose how many website bidders to
        drive. Tokens are minted on the bid server for users on that sale’s site.
      </p>

      <form className="card" onSubmit={adminToken ? begin : connect} style={{ marginTop: 16 }}>
        <div className="row">
          <div className="field" style={{ flex: 1 }}>
            <label>Bid server</label>
            <input value={setup.backendUrl} onChange={onChange('backendUrl')} />
          </div>
          <div className="field">
            <label>Site name</label>
            <input value={setup.siteName} onChange={onChange('siteName')} />
          </div>
        </div>
        <div className="row" style={{ marginTop: 12 }}>
          <div className="field">
            <label>Admin / clerk email</label>
            <input type="email" value={setup.email || ''} onChange={onChange('email')} required />
          </div>
          <div className="field">
            <label>Password</label>
            <input type="password" value={setup.password || ''} onChange={onChange('password')} required={!adminToken} />
          </div>
          {!adminToken ? (
            <button className="btn" type="submit" disabled={busy}>
              {busy ? 'Connecting…' : 'Connect'}
            </button>
          ) : null}
        </div>

        {adminToken ? (
          <>
            <div className="row" style={{ marginTop: 16 }}>
              <div className="field" style={{ flex: 1 }}>
                <label>Sale</label>
                <select
                  value={setup.saleUuid || ''}
                  onChange={(e) => {
                    const sale = sales.find((s) => s.uuid === e.target.value);
                    setSetup((s) => ({
                      ...s,
                      saleUuid: e.target.value,
                      saleNid: sale ? sale.nid : '',
                    }));
                  }}
                >
                  <option value="">Select a sale</option>
                  {liveSales.map((sale) => (
                    <option key={sale.uuid} value={sale.uuid}>
                      {sale.title} ({sale.status}) #{sale.nid}
                    </option>
                  ))}
                </select>
              </div>
              <div className="field" style={{ minWidth: 120 }}>
                <label>Bidders</label>
                <input
                  type="number"
                  min="1"
                  max="40"
                  value={setup.count || 4}
                  onChange={onChange('count')}
                />
              </div>
              <div className="field">
                <label>Find sale</label>
                <input
                  value={search}
                  placeholder="title or nid"
                  onChange={(e) => setSearch(e.target.value)}
                  onBlur={refreshSales}
                />
              </div>
              <button className="btn" type="submit" disabled={busy}>
                {busy ? 'Starting…' : 'Start simulation'}
              </button>
            </div>
            <p className="muted" style={{ marginTop: 8 }}>
              {sales.length} sales loaded. Website paddles on the sale’s site are reused;
              extra site users get a paddle if you ask for more.
            </p>
          </>
        ) : null}

        {error ? <p className="error">{error}</p> : null}
      </form>
    </div>
  );
}

function SimScreen({ setup, session, onExit }) {
  const first = session.bidders[0];
  const config = useMemo(
    () => bidderConfig(setup.backendUrl, first, session.pusher),
    [setup.backendUrl, first, session.pusher],
  );
  const { state, reload, onSharedEvent } = useSharedSale({
    config,
    saleUuid: session.sale.uuid,
  });

  const sale = state.sale;
  const activeItemId = state.saleState === 'success' ? sale.item : null;
  const activeItem = activeItemId != null ? state.items.byId[activeItemId] || null : null;
  const calculated = activeItem?.calculated || null;
  const effectiveStatus =
    calculated && state.asyncGoingItemStatus && calculated.status === ITEM_STATUS.OPEN
      ? ITEM_STATUS.GOING
      : calculated?.status || null;
  const currency = sale?.currency;
  const price = calculated
    ? getPriceForBidder(calculated, state.clerkHighestQueuedBidData)
    : null;

  return (
    <div className="page">
      <div className="row" style={{ justifyContent: 'space-between', marginBottom: 16 }}>
        <div>
          <h1 style={{ margin: 0 }}>{session.sale.title}</h1>
          <div className="muted">
            {session.sale.status}
            {activeItem ? ` · Lot ${activeItem.lotId || activeItemId}` : ''}
            {effectiveStatus ? ` · ${effectiveStatus}` : ''}
            {price && sale ? ` · ${showAmountInCurrency(sale, currency, price.amount)}` : ''}
          </div>
        </div>
        <div className="row">
          <button className="btn btn-ghost" type="button" onClick={reload}>
            Reload sale
          </button>
          <button className="btn btn-ghost" type="button" onClick={onExit}>
            Change sale
          </button>
        </div>
      </div>

      {state.saleState === 'loading' || state.saleState === 'notAsked' ? (
        <p className="muted">Loading auction…</p>
      ) : null}
      {state.saleState === 'failure' ? (
        <p className="error">{state.saleError || 'Failed to load sale'}</p>
      ) : null}

      {session.available < session.requested ? (
        <p className="muted">
          Requested {session.requested} bidders, using {session.bidders.length} (all available
          on this site).
        </p>
      ) : null}

      <div className="grid">
        {session.bidders.map((bidder) => (
          <BidderCard
            key={bidder.uid}
            bidder={bidder}
            config={bidderConfig(setup.backendUrl, bidder, session.pusher)}
            saleUuid={session.sale.uuid}
            sharedState={state}
            onSharedEvent={onSharedEvent}
          />
        ))}
      </div>
    </div>
  );
}
