// common/services/liveSaleApi.js
//
// Live-sale network calls — a React implementation of the Elm bidder
// live-auction page's fetch layer. All functions take the app `config`
// (ConfigContext value: { backendUrl, accessToken, serverless, env, ... })
// and return a normalized `{ ok, ... }` result instead of throwing — the
// same convention as common/domain/bidding.js.
//
// DELIBERATELY NOT part of DataCache: live-auction data must never be served
// from a cache. Only bidder info keeps flowing through
// DataCache.fetchBidderIds / invalidateBidderIds.
//
// SOURCE OF TRUTH (Elm, circuit-bid/client/src/elm):
//   - Pages/Sale/Update.elm fetchSale (943-953), fetchSaleTitleFromJson /
//     fetchCurrenciesInfoFromJson (958-975), sendConnectedUserEvent (921-938)
//   - ItemManager/Update.elm fetchItems (212-225),
//     fetchItemsOwnPlacedBids (245-261), fetchStaticItem/fetchAllStaticItems
//   - Message/Update.elm fetchMessages (17-30)
//   - Bid/Update.elm placeBid (23-47) + Bid/Encoder.elm encodeBid (23-42)
//   - QueuedRequest/Decoder.elm (response: data.task_id)
//   - Backend/CreditRequest/Endpoint.elm ("api/credit_requests") + Encoder.elm
//   - Backend/ConnectedUser/Encoder.elm encodeConnectedUserEvent

import fetchData from '../utils/Util';
import {
  currenciesInfoFromBatch,
  normalizeLotMap,
  normalizeSale,
  saleTitleFromBatch,
} from '../domain/liveSale/saleModel';
import {
  normalizeCalculatedItem,
  normalizeStaticItem,
} from '../domain/liveSale/items';
import { messagesFromResponse } from '../domain/liveSale/messages';

const jsonHeaders = (config) => ({
  'Content-Type': 'application/json',
  'access-token': config.accessToken,
});

async function readErrorMessage(response, fallback) {
  try {
    const errorData = await response.json();
    return errorData.title || errorData.detail || errorData.message || fallback;
  } catch (parseError) {
    return fallback;
  }
}

/**
 * GET /api/sales/<uuid>?access_token=…&loadByFieldName=uuid
 * (Pages/Sale/Update.elm fetchSale). The token travels as a QUERY PARAM here
 * — the Elm comment explains the request is shaped to be served by Varnish;
 * do not move it to a header.
 *
 * @returns {Promise<{ok:boolean, sale?:object, lotMap?:Array, error?:string}>}
 */
export async function fetchLiveSale(config, saleUuid) {
  try {
    const url =
      `${config.backendUrl}/api/sales/${encodeURIComponent(saleUuid)}` +
      `?access_token=${encodeURIComponent(config.accessToken || '')}` +
      '&loadByFieldName=uuid';
    const response = await fetchData(url, {}, config);
    if (!response.ok) {
      return { ok: false, error: await readErrorMessage(response, 'Failed to fetch sale') };
    }
    const json = await response.json();
    const raw = Array.isArray(json.data) ? json.data[0] : json.data?.['0'];
    if (!raw) {
      return { ok: false, error: 'Empty sale response' };
    }
    return {
      ok: true,
      sale: normalizeSale(raw),
      lotMap: normalizeLotMap(raw.lots),
    };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * GET /api/items/<id1>,<id2>,… (ItemManager/Update.elm fetchItems). Ids are
 * de-duplicated like the Elm Set fold.
 *
 * @param {number[]} itemIds
 * @param {number} nowMs  Client clock for the auto-clerk skew adjustment.
 * @returns {Promise<{ok:boolean, entries?:Array<{uuid, calculated}>, error?:string}>}
 */
export async function fetchCalculatedItems(config, itemIds, nowMs) {
  const uniqueIds = [...new Set((itemIds || []).map((id) => String(id)))];
  if (uniqueIds.length === 0) {
    return { ok: true, entries: [] };
  }
  try {
    const response = await fetchData(
      `${config.backendUrl}/api/items/${uniqueIds.join(',')}`,
      { headers: { 'access-token': config.accessToken } },
      config,
    );
    if (!response.ok) {
      return { ok: false, error: await readErrorMessage(response, 'Failed to fetch items') };
    }
    const json = await response.json();
    const list = Array.isArray(json.data) ? json.data : [];
    return {
      ok: true,
      entries: list
        .filter((raw) => raw && raw.uuid != null)
        .map((raw) => ({ uuid: raw.uuid, calculated: normalizeCalculatedItem(raw, nowMs) })),
    };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * GET /api/items?sale_uuid=…&placed_bids=1&sort=-id — the items the bidder
 * has placed bids on, for the bid-history table (ItemManager/Update.elm
 * fetchItemsOwnPlacedBids).
 */
export async function fetchOwnPlacedBidItems(config, saleUuid, nowMs) {
  try {
    const params = new URLSearchParams({
      sale_uuid: saleUuid,
      placed_bids: '1',
      sort: '-id',
    });
    const response = await fetchData(
      `${config.backendUrl}/api/items?${params.toString()}`,
      { headers: { 'access-token': config.accessToken } },
      config,
    );
    if (!response.ok) {
      return { ok: false, error: await readErrorMessage(response, 'Failed to fetch bid items') };
    }
    const json = await response.json();
    const list = Array.isArray(json.data) ? json.data : [];
    return {
      ok: true,
      entries: list
        .filter((raw) => raw && raw.uuid != null)
        .map((raw) => ({ uuid: raw.uuid, calculated: normalizeCalculatedItem(raw, nowMs) })),
    };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

