/**
 * POST /api/messages with type private_by_bidder — send a private message to
 * the clerk (Message/Update.elm sendBidderPrivateMessage). The sent message
 * comes back via the `message__create` pusher echo on the user's private
 * channel; there is no local insert.
 * @returns {Promise<{ok:boolean, error?:string}>}
 */
export async function sendPrivateMessage(config, { saleUuid, text }) {
  const body = {
    type: 'private_by_bidder',
    sale_uuid: saleUuid,
    text,
  };
  try {
    const response = await fetchData(
      `${config.backendUrl}/api/messages`,
      {
        method: 'POST',
        headers: jsonHeaders(config),
        body: JSON.stringify(body),
      },
      config,
    );
    if (!response.ok) {
      return { ok: false, error: await readErrorMessage(response, 'Failed to send message') };
    }
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * How many lots of static data to fetch beyond what is displayed
 * (ItemManager/Update.elm staticLookaheadCount).
 */
export const STATIC_LOOKAHEAD = 2;

/**
 * Fetch static item data from the backoffice items-json endpoint for the
 * given uuids — the displayed lots plus the look-ahead. The S3 batch
 * files are gone; api/items-json?json_type=live is the only item-data
 * source. Every element also carries the sale-level extras, so the
 * translated sale title and the exchange-rate table ride along from the
 * first element (ItemManager/Decoder.elm decodeStaticItemsFromResponse).
 *
 * @returns {Promise<{ok:boolean, staticItems:Array, saleTitle:?string,
 *                    currenciesInfo:object}>}
 */
export async function fetchStaticItemsJson(backofficeUrl, languageCode, uuids) {
  const empty = { ok: false, staticItems: [], saleTitle: null, currenciesInfo: {} };
  if (!backofficeUrl || !uuids || uuids.length === 0) {
    return empty;
  }
  try {
    const params = new URLSearchParams({
      json_type: 'live',
      language: languageCode,
      uuids: uuids.join(','),
    });
    const response = await fetch(`${backofficeUrl}/api/items-json?${params.toString()}`);
    if (!response.ok) {
      return empty;
    }
    const body = await response.json();
    const raws = Array.isArray(body?.data) ? body.data : [];
    const first = raws[0] || null;
    return {
      ok: true,
      staticItems: raws.map(normalizeStaticItem).filter(Boolean),
      // The per-element sale extras have the same keys as the batch
      // envelope, so the batch extractors apply as-is.
      saleTitle: saleTitleFromBatch(first),
      currenciesInfo: currenciesInfoFromBatch(first),
    };
  } catch (err) {
    return empty;
  }
}

/**
 * Lightweight live-status probe for a sale. The Drupal sales-public records
 * carry NO live-auction state (their `status` is just published_on_site /
 * finished, and `saleLiveLink` stays false even mid-auction — verified
 * against a running live sale), so list/catalog UIs must ask the bid server.
 * Anonymous, cacheable, ~tens of KB.
 *
 * @returns {Promise<{ok:boolean, status?:string}>} status is a SALE_STATUS
 *   value ('open_live' while the live auction runs).
 */
export async function fetchSaleLiveStatus(config, saleUuid) {
  if (!config?.backendUrl || !saleUuid) {
    return { ok: false };
  }
  try {
    // fields=uuid,status shrinks the response from ~77KB (incl. lot map) to
    // ~200 bytes — cheap enough to probe every sale on a list page.
    const url =
      `${config.backendUrl}/api/v1.0/sales/${encodeURIComponent(saleUuid)}` +
      '?loadByFieldName=uuid&fields=uuid,status';
    const response = await fetchData(url, {}, config);
    if (!response.ok) {
      return { ok: false };
    }
    const json = await response.json();
    const raw = Array.isArray(json.data) ? json.data[0] : null;
    return raw && raw.status ? { ok: true, status: raw.status } : { ok: false };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * POST /api/bids — the LIVE (internet) bid. Differs from the pre-live
 * bidding.js placeBid: the body carries the numeric item id and bidder
 * number plus the livequeue tag, and the response is only a task id — the
 * outcome arrives asynchronously via the `livequeue__post_execute` pusher
 * event (Bid/Update.elm placeBid + Bid/Encoder.elm encodeBid).
 *
 * @param {object} args
 * @param {string} args.saleUuid
 * @param {number} args.itemId        Numeric item id (NOT the uuid).
 * @param {number} args.bidderNumber  The user's website bidder number.
 * @param {number} args.amount
 * @returns {Promise<{ok:boolean, taskId?:string, error?:string}>}
 */
export async function placeLiveBid(config, { saleUuid, itemId, bidderNumber, amount }) {
  const body = {
    amount: Number(amount) || 0,
    item: Number(itemId) || 0,
    bidder_id: Number(bidderNumber) || 0,
    type: 'internet',
    sale_uuid: String(saleUuid || ''),
    livequeue: true,
    tag: 'place_bid',
  };
  try {
    const response = await fetchData(
      `${config.backendUrl}/api/bids`,
      {
        method: 'POST',
        headers: jsonHeaders(config),
        body: JSON.stringify(body),
      },
      config,
    );
    if (!response.ok) {
      return { ok: false, error: await readErrorMessage(response, 'Bid failed') };
    }
    const json = await response.json();
    const taskId = json?.data?.task_id;
    if (taskId == null) {
      return { ok: false, error: 'Missing task_id in bid response' };
    }
    return { ok: true, taskId: String(taskId) };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/** Connected-user presence event names (Backend/ConnectedUser/Encoder.elm). */
export const CONNECTED_USER_EVENT = {
  HEARTBEAT: 'connected_users__sale__heartbeat',
  PLACE_BID_MOUSE_ENTER: 'connected_users__sale__place_bid__mouse_enter',
  PLACE_BID_MOUSE_LEAVE: 'connected_users__sale__place_bid__mouse_leave',
};

/**
 * POST <serverless base> — presence broadcast to the clerk's connected-users
 * panel (Pages/Sale/Update.elm sendConnectedUserEvent + ConnectedUser
 * Encoder). Callers gate on sale status LiveAuctionOpen + authenticated user;
 * failures are soft (presence is best-effort).
 *
 * @param {object} args
 * @param {string} args.event         One of CONNECTED_USER_EVENT.
 * @param {string} args.saleUuid
 * @param {(number|string)} args.bidderNumber  Website bidder number ('' when unknown).
 */
export async function sendConnectedUserEvent(config, { event, saleUuid, bidderNumber }) {
  if (!config.serverless) {
    return { ok: false, error: 'No serverless URL configured' };
  }
  const body = {
    event,
    saleUuid,
    bidderNumber: bidderNumber != null ? String(bidderNumber) : '',
    // Legacy dummy field the endpoint still expects (Encoder.elm "@todo").
    item: '1',
    env: config.env || '',
  };
  try {
    const response = await fetch(config.serverless, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    return { ok: response.ok };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * GET /api/credit_requests?sale_uuid=…&user_uuid=…
 * (Backend/CreditRequest/Endpoint.elm + Encoder.elm
 * encodeCreditRequestParams). Returns the raw data array — the reducer
 * stores credit requests as-is.
 */
export async function fetchCreditRequests(config, { saleUuid, userUuid }) {
  try {
    const params = new URLSearchParams({ sale_uuid: saleUuid });
    if (userUuid) params.append('user_uuid', userUuid);
    const response = await fetchData(
      `${config.backendUrl}/api/credit_requests?${params.toString()}`,
      { headers: { 'access-token': config.accessToken } },
      config,
    );
    if (!response.ok) {
      return {
        ok: false,
        error: await readErrorMessage(response, 'Failed to fetch credit requests'),
      };
    }
    const json = await response.json();
    return { ok: true, creditRequests: Array.isArray(json.data) ? json.data : [] };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * POST /api/credit_requests — request more credit
 * (Backend/CreditRequest/Encoder.elm encodeCreateInfo).
 */
export async function createCreditRequest(config, { saleUuid, userUuid, amount }) {
  const body = {
    sale_uuid: saleUuid,
    user_uuid: userUuid,
    amount: Number(amount) || 0,
  };
  try {
    const response = await fetchData(
      `${config.backendUrl}/api/credit_requests`,
      {
        method: 'POST',
        headers: jsonHeaders(config),
        body: JSON.stringify(body),
      },
      config,
    );
    if (!response.ok) {
      return {
        ok: false,
        error: await readErrorMessage(response, 'Failed to create credit request'),
      };
    }
    const json = await response.json();
    const created = Array.isArray(json.data) ? json.data[0] : json.data;
    return { ok: true, creditRequest: created || null };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}
