// util.js
import AsyncStorage from '@react-native-async-storage/async-storage';

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const fetchData = async (url, options = {}, config = {}) => {
  if (config.useMockData) {
    await delay(500); // Simulate a delay to mimic an actual API call

    const mockResponse = {
      'api-me': {
        ok: true,
        json: () => Promise.resolve(require('./mockup/api-me.json')),
      },
      'api-client-address': {
        ok: true,
        json: () => Promise.resolve(require('./mockup/api-client-address.json')),
      },
      'api-items-json': {
        ok: true,
        json: () => Promise.resolve(require('./mockup/api-items-json.json')),
      },
    };

    const mockData = mockResponse[options.mockData] || null;

    if (mockData) {
      return mockData;
    } else {
      throw new Error(`Mock data not found for URL: ${url}`);
    }
  }

  const response = await fetch(url, options);

  // Handle 403 response by setting AsyncStorage flag
  if (response.status >= 400 && response.status < 500) {
    await AsyncStorage.setItem('force_bo_refresh', '1');
  }

  return response;
};

export default fetchData;

const B64_CHARS =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

// UTF-8 encode a JS string to an array of bytes (handles surrogate pairs).
const utf8Bytes = (str) => {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let code = str.charCodeAt(i);
    if (code < 0x80) {
      bytes.push(code);
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    } else if (code >= 0xd800 && code <= 0xdbff) {
      const hi = code;
      const lo = str.charCodeAt(++i);
      code = 0x10000 + ((hi & 0x3ff) << 10) + (lo & 0x3ff);
      bytes.push(
        0xf0 | (code >> 18),
        0x80 | ((code >> 12) & 0x3f),
        0x80 | ((code >> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    } else {
      bytes.push(
        0xe0 | (code >> 12),
        0x80 | ((code >> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    }
  }
  return bytes;
};

/**
 * Base64-encode a (UTF-8) string. React Native's Hermes/JSC core does NOT
 * reliably provide a global `btoa`, so we implement it here for use in HTTP
 * Basic auth (login) and anywhere else base64 is needed. Deterministic and
 * dependency-free.
 */
export const base64Encode = (input) => {
  const bytes = utf8Bytes(String(input));
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    const triple = (b0 << 16) | (b1 << 8) | b2;
    out += B64_CHARS[(triple >> 18) & 0x3f];
    out += B64_CHARS[(triple >> 12) & 0x3f];
    out += i + 1 < bytes.length ? B64_CHARS[(triple >> 6) & 0x3f] : '=';
    out += i + 2 < bytes.length ? B64_CHARS[triple & 0x3f] : '=';
  }
  return out;
};