import React from 'react';
import { useTranslation } from 'react-i18next';
import { ALERT } from '@common/domain/liveSale/reducer';

const ALERT_CONFIG = {
  [ALERT.BID_ACCEPTED]: { key: 'liveauctionpage.alertBidAccepted', level: 'success' },
  [ALERT.BID_REJECTED]: { key: 'liveauctionpage.alertBidRejected', level: 'error' },
  [ALERT.BID_REJECTED_CREDIT_LIMIT]: {
    key: 'liveauctionpage.alertBidRejectedCreditLimit',
    level: 'error',
  },
  [ALERT.BID_REJECTED_BIDDER_MAX_LIMIT]: {
    key: 'liveauctionpage.alertBidRejectedBidderMax',
    level: 'error',
  },
  [ALERT.BID_REJECTED_DUPLICATE_AMOUNT]: {
    key: 'liveauctionpage.alertBidRejectedDuplicate',
    level: 'error',
  },
  [ALERT.OUTBID]: { key: 'liveauctionpage.alertOutbid', level: 'notice' },
  [ALERT.OWN_BID_REVOKED]: { key: 'liveauctionpage.alertOwnBidRevoked', level: 'error' },
  [ALERT.OWN_BID_REVOKED_TO_FLOOR]: {
    key: 'liveauctionpage.alertOwnBidRevokedToFloor',
    level: 'error',
  },
  [ALERT.UNRECOGNIZED_CREDENTIALS]: {
    key: 'liveauctionpage.alertUnrecognizedCredentials',
    level: 'error',
  },
};

export default function AlertBanner({ alert, formatAmount }) {
  const { t: tr } = useTranslation();
  if (!alert) {
    return null;
  }
  const cfg = ALERT_CONFIG[alert.type];
  if (!cfg) {
    return null;
  }
  const amount =
    alert.amount != null && formatAmount ? formatAmount(alert.amount) : alert.amount;
  return <div className={`banner ${cfg.level}`}>{tr(cfg.key, { amount })}</div>;
}
