import React from 'react';
import { useTranslation } from 'react-i18next';
import { ITEM_STATUS } from '@common/domain/liveSale/items';

/**
 * Web port of native/src/screens/live/components/BidButton.js
 * Same terminal-state blocks as the live app (Elm "Bid button" spec).
 */
export default function BidButton({
  status,
  isHighestBidder,
  amountText,
  soldAmountText,
  maxBidText,
  bidLocked,
  canDecrement,
  onPlaceBid,
  onIncrement,
  onDecrement,
  onPressIn,
  onPressOut,
}) {
  const { t: tr } = useTranslation();

  const messageBlock = (text, tone = 'muted') => (
    <div className={`message-block ${tone}`}>{text}</div>
  );

  if (status === ITEM_STATUS.PAUSED) {
    return messageBlock(tr('liveauctionpage.standby'));
  }
  if (status === ITEM_STATUS.SOLD) {
    return isHighestBidder
      ? messageBlock(tr('liveauctionpage.youWonThisLotFor', { amount: soldAmountText }), 'win')
      : messageBlock(tr('liveauctionpage.soldForAmount', { amount: soldAmountText }));
  }
  if (status === ITEM_STATUS.UNSOLD) {
    return messageBlock(tr('liveauctionpage.statusUnsold'));
  }
  if (status === ITEM_STATUS.WITHDRAWN) {
    return messageBlock(tr('liveauctionpage.lotWithdrawn'), 'danger');
  }
  if (status !== ITEM_STATUS.OPEN && status !== ITEM_STATUS.GOING) {
    return null;
  }

  if (isHighestBidder) {
    return (
      <div>
        {maxBidText ? (
          <div className="muted" style={{ textAlign: 'center', marginTop: 8 }}>
            {tr('livebidform.yourMaxBid', { amount: maxBidText })}
          </div>
        ) : null}
        {messageBlock(tr('livebidform.highestBidderMessage'), 'win')}
      </div>
    );
  }

  const going = status === ITEM_STATUS.GOING;
  return (
    <div className="bid-row">
      <button
        type="button"
        className="step-btn"
        disabled={bidLocked || !canDecrement}
        onClick={onDecrement}
      >
        −
      </button>
      <button
        type="button"
        className={`place-bid ${going ? 'going' : 'open'}`}
        disabled={bidLocked}
        onClick={onPlaceBid}
        onMouseEnter={onPressIn}
        onMouseLeave={onPressOut}
      >
        {bidLocked ? '…' : tr('livebidform.placeBid', { amount: amountText })}
      </button>
      <button type="button" className="step-btn" disabled={bidLocked} onClick={onIncrement}>
        +
      </button>
    </div>
  );
}
