// common/domain/liveSale/messages.js
//
// Pure normalization of the live-sale activity stream (clerk messages + bid
// events) — a React implementation of the Elm bidder live-auction page.
//
// SOURCE OF TRUTH (Elm, circuit-bid/client/src/elm):
//   - Message/Model.elm    -> MESSAGE_TYPE
//   - Message/Decoder.elm  -> normalizeMessage / messagesFromResponse
//   - Message/Utils.elm    -> getItemsIds
//   - Message/Update.elm   -> addMessage (cons — newest first)
//   - Pusher/Decoder.elm   -> the seconds->ms timestamp fix for
//                             `message__create` payloads
//   - Pages/Sale/Update.elm (BidDelete branch, lines 1224-1265)
//                          -> syntheticDeleteMessage
//
// A message is:
//   { id, timestamp (ms), type, itemId?, bidKey?, text?, itemStatus? }
// and the stream is an array ordered newest-first (matching the server's
// `sort=-id` plus addMessage consing to the front).
//
// This module is pure: no network, no React, no i18n.

import { ITEM_STATUS } from './items';

export const MESSAGE_TYPE = {
  BID_ACCEPTED: 'bid_accepted',
  BID_CHANGED_TO_FLOOR: 'bid_changed_to_floor',
  BID_DELETED: 'bid_deleted',
  BID_OUTBID: 'bid_outbid',
  BID_REJECTED: 'bid_rejected',
  BID_REJECTED_BIDDER_MAX: 'bid_rejected_bidder_max',
  BID_REJECTED_CREDIT_LIMIT: 'bid_rejected_credit_limit',
  BID_REJECTED_BELOW_MINIMUM: 'bid_rejected_below_minimum',
  CLERK_PUBLIC: 'clerk_public',
  ITEM_UPDATE: 'item_update',
  PRIVATE_BY_BIDDER: 'private_by_bidder',
  PRIVATE_BY_CLERK: 'private_by_clerk',
  SALE_UPDATE_ACTIVE_ITEM: 'sale_update_active_item',
};

// arguments.status -> message type (Message/Decoder.elm decodeBidMessage).
const BID_STATUS_TO_TYPE = {
  accepted: MESSAGE_TYPE.BID_ACCEPTED,
  changed_to_floor: MESSAGE_TYPE.BID_CHANGED_TO_FLOOR,
  deleted: MESSAGE_TYPE.BID_DELETED,
  outbid: MESSAGE_TYPE.BID_OUTBID,
  rejected: MESSAGE_TYPE.BID_REJECTED,
  rejected_over_bidder_max: MESSAGE_TYPE.BID_REJECTED_BIDDER_MAX,
  rejected_over_credit_limit: MESSAGE_TYPE.BID_REJECTED_CREDIT_LIMIT,
  rejected_bellow_minimum: MESSAGE_TYPE.BID_REJECTED_BELOW_MINIMUM,
};

/**
 * Item status carried inside a message's arguments (Message/Decoder.elm
 * decodeItemStatusFromMessage): either a live clerk status (open/going/
 * paused) or a closed outcome (sold/unsold/withdrawn).
 */
function itemStatusFromMessage(args) {
  switch (args?.status) {
    case 'open':
      return ITEM_STATUS.OPEN;
    case 'going':
      return ITEM_STATUS.GOING;
    case 'paused':
      return ITEM_STATUS.PAUSED;
    case 'sold':
      return ITEM_STATUS.SOLD;
    case 'unsold':
      return ITEM_STATUS.UNSOLD;
    case 'withdrawn':
      return ITEM_STATUS.WITHDRAWN;
    default:
      return null;
  }
}

/**
 * Normalize a raw message timestamp to ms. REST payloads carry ms (or an ISO
 * string); pusher `message__create` payloads carry unix SECONDS — Elm fixes
 * those by multiplying by 1000 (Pusher/Decoder.elm convertTimestampFromServer),
 * so callers pass `fromPusher: true` for that path.
 */
function normalizeTimestamp(raw, fromPusher) {
  if (raw == null) return 0;
  if (typeof raw === 'string' && Number.isNaN(Number(raw))) {
    const parsed = Date.parse(raw);
    return Number.isNaN(parsed) ? 0 : parsed;
  }
  const num = Number(raw) || 0;
  return fromPusher ? num * 1000 : num;
}

/**
 * One raw message -> normalized message, or null for unknown types
 * (Message/Decoder.elm decodeMessage/decodeMessageType; the Elm decoder fails
 * hard — we drop the single message instead).
 *
 * @param {object} raw   { id, timestamp, type, arguments: {...} }
 * @param {object} [opts]
 * @param {boolean} [opts.fromPusher=false]  Apply the seconds->ms fix.
 */
export function normalizeMessage(raw, { fromPusher = false } = {}) {
  if (!raw || raw.id == null) return null;
  const args = raw.arguments || {};
  const base = {
    id: String(raw.id),
    timestamp: normalizeTimestamp(raw.timestamp, fromPusher),
  };

  switch (raw.type) {
    case 'bid_create':
    case 'bid_delete': {
      const type = BID_STATUS_TO_TYPE[args.status];
      if (!type) return null;
      return {
        ...base,
        type,
        itemId: parseInt(args.item_id) || 0,
        bidKey: args.bid_key != null ? String(args.bid_key) : null,
      };
    }
    case 'item_update':
      return {
        ...base,
        type: MESSAGE_TYPE.ITEM_UPDATE,
        itemId: parseInt(args.item_id) || 0,
        itemStatus: itemStatusFromMessage(args),
      };
    case 'sale_update':
      return {
        ...base,
        type: MESSAGE_TYPE.SALE_UPDATE_ACTIVE_ITEM,
        itemId: parseInt(args.item_id) || 0,
        itemStatus: itemStatusFromMessage(args),
      };
    case 'public_by_clerk':
      return {
        ...base,
        type: MESSAGE_TYPE.CLERK_PUBLIC,
        text: args.text || '',
      };
    // Private bidder<->clerk chat. `userId` / `bidderNumber` / `name`
    // always describe the BIDDER side of the conversation, for both
    // directions (sender of by_bidder, recipient of by_clerk).
    case 'private_by_bidder':
    case 'private_by_clerk':
      return {
        ...base,
        type:
          raw.type === 'private_by_bidder'
            ? MESSAGE_TYPE.PRIVATE_BY_BIDDER
            : MESSAGE_TYPE.PRIVATE_BY_CLERK,
        text: args.text || '',
        userId: parseInt(args.user_id) || 0,
        bidderNumber: parseInt(args.bidder_number) || null,
        name: args.name || '',
      };
    default:
      return null;
  }
}

/**
 * Whether a normalized message belongs to the private bidder<->clerk chat.
 */
export function isPrivateMessage(message) {
  return (
    message?.type === MESSAGE_TYPE.PRIVATE_BY_BIDDER ||
    message?.type === MESSAGE_TYPE.PRIVATE_BY_CLERK
  );
}

/**
 * The GET /api/messages response -> normalized stream, newest first
 * (Message/Decoder.elm decodeMessagesFromResponse; the request already sorts
 * `-id`). Unknown message types are dropped.
 */
export function messagesFromResponse(json) {
  const list = Array.isArray(json?.data) ? json.data : [];
  return list.map((raw) => normalizeMessage(raw)).filter(Boolean);
}

/**
 * Prepend a message to the stream (Message/Update.elm addMessage — cons).
 * A message with an id already present replaces the existing entry instead
 * of duplicating it (EveryDictList.cons semantics on an existing key).
 */
export function addMessage(messages, message) {
  if (!message) return messages;
  const rest = messages.filter((m) => m.id !== message.id);
  return [message, ...rest];
}

/**
 * Synthetic stream row for a plain bid delete (Pages/Sale/Update.elm
 * BidDelete branch): the backend pushes no `message__create` for plain
 * deletes (it does for changed_to_floor), so the page fabricates one locally.
 * The `synthetic-delete-<ms>` id shape is the Elm one.
 */
export function syntheticDeleteMessage(itemId, bidKey, nowMs) {
  return {
    id: `synthetic-delete-${Math.round(nowMs)}`,
    timestamp: nowMs,
    type: MESSAGE_TYPE.BID_DELETED,
    itemId,
    bidKey: bidKey != null ? String(bidKey) : null,
  };
}

/**
 * The item ids referenced by the stream (Message/Utils.elm getItemsIds) —
 * drives the lazy calculated-item fetch so every row can show lot data.
 * ClerkPublic and BidRejectedBellowMinimum rows carry no item id in Elm
 * (they fall through that function's `_ ->` branch).
 */
export function getItemsIds(messages) {
  const skip = [
    MESSAGE_TYPE.CLERK_PUBLIC,
    MESSAGE_TYPE.BID_REJECTED_BELOW_MINIMUM,
    MESSAGE_TYPE.PRIVATE_BY_BIDDER,
    MESSAGE_TYPE.PRIVATE_BY_CLERK,
  ];
  const ids = [];
  (messages || []).forEach((m) => {
    if (m.itemId != null && !skip.includes(m.type) && !ids.includes(m.itemId)) {
      ids.push(m.itemId);
    }
  });
  return ids;
}
