const LOCAL_DEFAULTS = {
  backendUrl: 'https://circuit-bid.ddev.site:4443',
  siteName: 'backoffice-joelshafer',
};

const TEST_DEFAULTS = {
  backendUrl: 'https://test-bids-eu.circuitauction.com',
  siteName: 'backoffice-hk-eu',
};

export function isLocalHostName(hostname) {
  const host = hostname || '';
  return host === 'localhost' || host === '127.0.0.1' || /ddev\.site$/.test(host);
}

export function defaultsForHost(hostname) {
  if (typeof hostname !== 'string' || isLocalHostName(hostname)) {
    return { ...LOCAL_DEFAULTS };
  }
  return { ...TEST_DEFAULTS };
}

export const DEFAULTS = defaultsForHost(
  typeof window !== 'undefined' ? window.location.hostname : 'localhost',
);

function envForBackend(backendUrl) {
  return /ddev\.site|localhost|127\.0\.0\.1/.test(backendUrl || '') ? 'local' : 'test';
}

export function loadSetup() {
  try {
    const raw = localStorage.getItem('bidder-simulator-setup');
    if (raw) {
      return { ...DEFAULTS, ...JSON.parse(raw) };
    }
  } catch (e) {
    // ignore
  }
  return { ...DEFAULTS, email: '', password: '' };
}

export function saveSetup(setup) {
  const { password, ...rest } = setup;
  localStorage.setItem('bidder-simulator-setup', JSON.stringify(rest));
}

async function readError(res) {
  try {
    const data = await res.json();
    return data.error || data.title || data.message || `HTTP ${res.status}`;
  } catch (e) {
    return `HTTP ${res.status}`;
  }
}

export async function loginAdmin({ backendUrl, siteName, email, password }) {
  const credentials = btoa(`${email}:${password}`);
  const res = await fetch(
    `${backendUrl.replace(/\/$/, '')}/api/login-token?site=${encodeURIComponent(siteName)}`,
    { headers: { Authorization: `Basic ${credentials}` } },
  );
  if (!res.ok) {
    return { ok: false, error: await readError(res) };
  }
  const data = await res.json();
  if (!data.access_token) {
    return { ok: false, error: 'No access_token in login response' };
  }
  return { ok: true, accessToken: data.access_token };
}

export async function fetchSales({ backendUrl, accessToken, search = '' }) {
  const url = new URL(`${backendUrl.replace(/\/$/, '')}/api/simulator/sales`);
  if (search) {
    url.searchParams.set('search', search);
  }
  const res = await fetch(url.toString(), {
    headers: { 'access-token': accessToken },
  });
  if (!res.ok) {
    return { ok: false, error: await readError(res) };
  }
  const data = await res.json();
  return { ok: true, ...data };
}

export async function startSession({ backendUrl, accessToken, saleUuid, saleNid, count }) {
  const res = await fetch(`${backendUrl.replace(/\/$/, '')}/api/simulator/session`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'access-token': accessToken,
    },
    body: JSON.stringify({
      sale_uuid: saleUuid || undefined,
      sale: saleNid || undefined,
      count,
    }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.error) {
    return { ok: false, error: data.error || `HTTP ${res.status}` };
  }
  return { ok: true, ...data };
}

export function bidderConfig(backendUrl, bidder, pusher, serverless) {
  return {
    backendUrl: backendUrl.replace(/\/$/, ''),
    accessToken: bidder.access_token,
    pusherKey: pusher,
    serverless: serverless || '',
    env: envForBackend(backendUrl),
    siteConfig: {},
    siteData: {},
    userData: { uuid: bidder.uuid, id: bidder.uid },
  };
}

export function bidderInfoFromRow(row) {
  return [
    {
      id: row.bidder_id,
      bidder_number: row.paddle,
      bidder_type: 'website',
      live_credit: row.live_credit,
      user_status: row.user_status,
      term_approval_date: row.term_approval_date,
    },
  ];
}
