// common/domain/liveSale/reducer.js
//
// The live sale page state machine — a React implementation of the Elm bidder
// live-auction page. Every action mirrors an Elm Msg constructor or pusher
// event branch; each case cites its source in
// circuit-bid/client/src/elm/Pages/Sale/Update.elm ("U:<lines>") or
// Model.elm ("M:<lines>").
//
// PURE: side effects (fetches, pusher, timers) live in the native useLiveSale
// hook, which dispatches into this reducer. State that is purely visual and
// resets on lot change (image-carousel index, description popup) lives in
// components keyed by the active item id, NOT here — remounting on lot change
// reproduces Elm's reset-on-item-change without reducer plumbing.
//
// DELIBERATE DEVIATION: Elm's PlaceBid branch (U:551-584) sets
// queuedRequestState = QueuedRequestCompleted while the POST is in flight,
// which re-enables the bid button between the tap and the HTTP response. We
// use Elm's own QueuedRequestSent state for that window instead
// (Bid/Utils.elm bidBeingPlaced treats sent+queued as "being placed"), so a
// double-tap cannot fire two bids.

import {
  emptyItemManager,
  getBid,
  insertCalculatedItems,
  insertStaticItems,
  isOwnBid,
  itemManagerFromLotMap,
  setCalculatedState,
  updateBidDict,
  CALC_STATE,
} from './items';
import { addMessage, isPrivateMessage, MESSAGE_TYPE, syntheticDeleteMessage } from './messages';

// ---------------------------------------------------------------------------
// Alert types (Alert.elm)
// ---------------------------------------------------------------------------

export const ALERT = {
  BID_ACCEPTED: 'bidAccepted',
  BID_REJECTED: 'bidRejected',
  BID_REJECTED_CREDIT_LIMIT: 'bidRejectedCreditLimit',
  BID_REJECTED_BIDDER_MAX_LIMIT: 'bidRejectedBidderMaxLimit',
  BID_REJECTED_DUPLICATE_AMOUNT: 'bidRejectedDuplicateAmount',
  OUTBID: 'outbid',
  OWN_BID_REVOKED: 'ownBidRevoked',
  OWN_BID_REVOKED_TO_FLOOR: 'ownBidRevokedToFloor',
  UNRECOGNIZED_CREDENTIALS: 'unrecognizedCredentials',
};

/** Minimum time an alert stays on screen while pusher events stream in
 * (U:368-397). */
export const ALERT_HOLD_MS = 3 * 1000;

/** Queued-bid hard timeout (U:81-120). */
export const QUEUED_REQUEST_TIMEOUT_MS = 15 * 1000;

/** ItemUpdate heartbeat: a queued bid older than this when an item__update
 * arrives means the livequeue result was lost (U:1121-1166). */
export const QUEUED_HEARTBEAT_MS = 5 * 1000;

/** Deferred lot transition, so "Sold for $X" stays readable (U:1094-1107). */
export const SALE_UPDATE_DEFER_MS = 2 * 1000;

export const QUEUED = {
  NONE: 'none',
  SENT: 'sent',
  QUEUED: 'queued',
  COMPLETED: 'completed',
  FAILED: 'failed',
};

const emptyQueuedRequest = () => ({
  state: QUEUED.NONE,
  taskId: null,
  startTime: null,
  error: null,
});

const emptyClerkQueuedBidsData = () => ({ bid: null, nextBid: null });

// ---------------------------------------------------------------------------
// Actions
// ---------------------------------------------------------------------------

export const ACTIONS = {
  // Data lifecycle (M:108-145 Msg)
  SALE_FETCH_STARTED: 'SALE_FETCH_STARTED', // Subscribe (U:600-611)
  HANDLE_FETCHED_SALE_OK: 'HANDLE_FETCHED_SALE_OK', // U:242-271
  HANDLE_FETCHED_SALE_ERR: 'HANDLE_FETCHED_SALE_ERR', // U:273-278
  HANDLE_FETCHED_SALE_TITLE: 'HANDLE_FETCHED_SALE_TITLE', // U:280-292
  HANDLE_FETCHED_CURRENCIES_INFO: 'HANDLE_FETCHED_CURRENCIES_INFO', // U:301-313
  HANDLE_FETCHED_STATIC_ITEMS: 'HANDLE_FETCHED_STATIC_ITEMS', // ItemManager U:116-121
  CALCULATED_ITEMS_LOADING: 'CALCULATED_ITEMS_LOADING', // ItemManager U:55-95
  HANDLE_FETCHED_CALCULATED_ITEMS_OK: 'HANDLE_FETCHED_CALCULATED_ITEMS_OK', // ItemManager U:130-147
  HANDLE_FETCHED_CALCULATED_ITEMS_ERR: 'HANDLE_FETCHED_CALCULATED_ITEMS_ERR', // ItemManager U:149-166
  MESSAGES_LOADING: 'MESSAGES_LOADING', // U:478-491
  HANDLE_FETCHED_MESSAGES_OK: 'HANDLE_FETCHED_MESSAGES_OK', // U:322-336
  HANDLE_FETCHED_MESSAGES_ERR: 'HANDLE_FETCHED_MESSAGES_ERR', // U:338-343
  HANDLE_FETCHED_CREDIT_REQUESTS: 'HANDLE_FETCHED_CREDIT_REQUESTS', // Backend/CreditRequest Fetch

  // Private bidder<->clerk chat (mirrors the Elm Pages/Sale privateMessages
  // fields). Gated on its own state slot so the public messages gate can't
  // swallow private pushes.
  PRIVATE_MESSAGES_LOADING: 'PRIVATE_MESSAGES_LOADING',
  HANDLE_FETCHED_PRIVATE_MESSAGES_OK: 'HANDLE_FETCHED_PRIVATE_MESSAGES_OK',
  HANDLE_FETCHED_PRIVATE_MESSAGES_ERR: 'HANDLE_FETCHED_PRIVATE_MESSAGES_ERR',
  PRIVATE_CHAT_SEEN: 'PRIVATE_CHAT_SEEN',

  // Bidding (M:109-128)
  BID_AMOUNT_INCREMENT: 'BID_AMOUNT_INCREMENT', // U:67-72
  BID_AMOUNT_DECREMENT: 'BID_AMOUNT_DECREMENT', // U:74-79
  PLACE_BID_SENT: 'PLACE_BID_SENT', // U:551-584 (see deviation note above)
  HANDLE_BID_PLACED_OK: 'HANDLE_BID_PLACED_OK', // U:202-218
  HANDLE_BID_PLACED_ERR: 'HANDLE_BID_PLACED_ERR', // U:220-229
  CHECK_QUEUED_REQUEST_TIMEOUT: 'CHECK_QUEUED_REQUEST_TIMEOUT', // U:81-120

  // Lot filmstrip (M:124-125)
  ITEMS_NEXT: 'ITEMS_NEXT', // U:414-429
  ITEMS_PREVIOUS: 'ITEMS_PREVIOUS', // U:431-446

  // Currency selector (M:143-144)
  SET_SELECTED_CURRENCY: 'SET_SELECTED_CURRENCY', // U:798-803

  // Deferred lot transition (M:145)
  APPLY_PENDING_SALE_UPDATE: 'APPLY_PENDING_SALE_UPDATE', // U:812-823

  // Realtime — a decoded pusherEvents.js event (U:359-412 HandlePusherEvent
  // -> updateFromPusher U:1056-1452)
  PUSHER_EVENT: 'PUSHER_EVENT',

  // Foreground catch-up: apply a freshly-refetched sale's mutable fields
  // WITHOUT the 2s defer and without rebuilding the item manager (which
  // would wipe loaded static/calculated data). `data` has the
  // normalizeSaleUpdate shape. No Elm counterpart — the web page never
  // backgrounds; RN sockets suspend, so we resync on foreground.
  SALE_SYNCED: 'SALE_SYNCED',

  // Full-state reset consumed (hook acknowledges needsFullReload)
  FULL_RELOAD_HANDLED: 'FULL_RELOAD_HANDLED',
};

// ---------------------------------------------------------------------------
// Initial state (M:77-105 emptyModel)
// ---------------------------------------------------------------------------

export const initialState = {
  saleState: 'notAsked', // WebData Sale
  sale: null,
  saleError: null,
  items: emptyItemManager(),
  nextBidIncrements: [],
  carouselPosition: 0,
  numberOfCarouselItems: 5,
  queuedRequest: emptyQueuedRequest(),
  clerkHighestQueuedBidData: emptyClerkQueuedBidsData(),
  asyncGoingItemStatus: false,
  messagesState: 'notAsked',
  messages: [],
  privateMessagesState: 'notAsked', // WebData MessageDict (private chat)
  privateMessages: [],
  privateUnread: 0, // clerk replies since the chat was last seen
  creditRequests: [],
  alert: null, // { at: ms, type: ALERT.*, amount: ?number }
  pendingSaleUpdate: null,
  selectedCurrency: null, // null = sale's own currency
  needsFullReload: false,
  // Livequeue results that arrived while no matching bid was queued — on a
  // fast backend the pusher result can beat the POST response that carries
  // the task id. HANDLE_BID_PLACED_OK checks this buffer so the button never
  // sticks on the spinner. No Elm counterpart (Elm silently drops these and
  // relies on the 15s timeout).
  recentLiveQueueResults: [],
};

// ---------------------------------------------------------------------------
// Carousel math (U:978-1053)
// ---------------------------------------------------------------------------

export function incrementItemSlider(items, carouselPosition) {
  const indexOfLastItem = Math.max(items.order.length - 1, 0);
  return Math.min(carouselPosition + 1, indexOfLastItem);
}

export function decrementItemSlider(items, carouselPosition) {
  return Math.max(Math.min(carouselPosition, items.order.length) - 1, 0);
}

/**
 * Center the filmstrip on the active lot (U:1010-1053). Faithful port,
 * including the "- 2 centers a 5-item carousel" rule and the clamp to
 * highestIndex (which Elm allows to go negative when there are fewer items
 * than carousel slots).
 */
export function calculateCarouselPosition(numberOfCarouselItems, itemId, items) {
  const highestIndex = items.order.length - numberOfCarouselItems;
  const found = items.order.indexOf(itemId);
  const currentItemIndex = found === -1 ? 0 : found;
  const centered = currentItemIndex < 2 ? 0 : currentItemIndex - 2;
  return centered > highestIndex ? highestIndex : centered;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const closeAllPopups = {}; // popup state lives in components; kept for symmetry

function recalcCarousel(state, items) {
  if (state.saleState !== 'success' || !state.sale) return state.carouselPosition;
  return calculateCarouselPosition(state.numberOfCarouselItems, state.sale.item, items);
}

/**
 * Apply a sale__update's fields (U:849-918 applySaleUpdate): update the sale
 * record, reset the per-lot bidding state, recenter the filmstrip, and flag a
 * full reload when the session changed (Elm calls the delayedReload port).
 */
function applySaleUpdate(state, updateData) {
  if (state.saleState !== 'success' || !state.sale) return state;

  const needsFullReload =
    state.needsFullReload || state.sale.session !== updateData.session;

  const sale = {
    ...state.sale,
    status: updateData.status,
    label: updateData.label,
    pausedMessage: updateData.pausedMessage,
    item: updateData.item,
    autoClerk: updateData.autoClerk,
  };
  // Only when the broadcast carries rates — empty may just mean an older
  // bid server (pre currencies_info).
  if (updateData.currenciesInfo && Object.keys(updateData.currenciesInfo).length > 0) {
    sale.currenciesInfo = updateData.currenciesInfo;
  }

  // The clerk's "clear message stream": drop every message at or below the
  // sale's clear point (message ids are numeric strings; synthetic local
  // entries have non-numeric ids and are kept).
  const clearId = updateData.messageClearId || 0;
  const messages =
    clearId > 0
      ? state.messages.filter((m) => {
          const numericId = parseInt(m.id, 10);
          return Number.isNaN(numericId) || numericId > clearId;
        })
      : state.messages;

  return {
    ...state,
    sale,
    messages,
    nextBidIncrements: [],
    carouselPosition: calculateCarouselPosition(
      state.numberOfCarouselItems,
      updateData.item,
      state.items,
    ),
    asyncGoingItemStatus: false,
    clerkHighestQueuedBidData: emptyClerkQueuedBidsData(),
    needsFullReload,
  };
}

/**
 * The ≥3s alert hold (U:368-397): pusher events stream almost continuously
 * during a live sale, and every one of them re-evaluates the alert — without
 * this, a BidAccepted toast would vanish within a frame.
 */
function heldAlert(state, now) {
  if (state.alert && now - state.alert.at < ALERT_HOLD_MS) {
    return state.alert;
  }
  return null;
}

/** Alert for the bidder's own bid outcome (U:1374-1396). */
function alertForOwnBidStatus(bidStatus, amount, now) {
  switch (bidStatus) {
    case 'accepted':
      return { at: now, type: ALERT.BID_ACCEPTED, amount };
    case 'rejected':
      return { at: now, type: ALERT.BID_REJECTED, amount };
    case 'rejected_over_credit_limit':
      return { at: now, type: ALERT.BID_REJECTED_CREDIT_LIMIT, amount };
    case 'rejected_over_bidder_max':
      return { at: now, type: ALERT.BID_REJECTED_BIDDER_MAX_LIMIT, amount };
    case 'outbid':
      return { at: now, type: ALERT.OUTBID, amount };
    default:
      return null;
  }
}

/**
 * Parse the duplicate-amount rejection out of a livequeue failure string
 * (U:1410-1427): "Cannot have duplicated amount <n> ..." — the 5th word is
 * the amount.
 */
export function parseDuplicateAmountError(error) {
  if (typeof error !== 'string' || !error.startsWith('Cannot have duplicated amount')) {
    return null;
  }
  const word = error.split(/\s+/)[4];
  return word != null && /^-?\d+$/.test(word) ? parseInt(word, 10) : null;
}

/**
 * Apply a livequeue place-bid result to the state (U:1367-1436 — the
 * success/failure completion shared by the live pusher path and the
 * buffered-result path).
 */
function applyLiveQueueResult(state, result, now, ownBidderNumbers) {
  if (result.kind === 'placeBidSuccess') {
    const bid = result.bid;
    const alert = isOwnBid(bid, ownBidderNumbers)
      ? alertForOwnBidStatus(bid.status, bid.amount, now)
      : null;
    return {
      ...state,
      queuedRequest: { state: QUEUED.COMPLETED, taskId: null, startTime: null, error: null },
      alert,
      nextBidIncrements: [],
    };
  }
  if (result.kind === 'placeBidFailure') {
    const duplicateAmount = parseDuplicateAmountError(result.error);
    const alert =
      duplicateAmount != null
        ? { at: now, type: ALERT.BID_REJECTED_DUPLICATE_AMOUNT, amount: duplicateAmount }
        : state.alert;
    return {
      ...state,
      queuedRequest: {
        state: QUEUED.FAILED,
        taskId: null,
        startTime: null,
        error: result.error,
      },
      alert,
    };
  }
  return state;
}

/** Upsert a raw credit request by id (Backend/CreditRequest HandleCreate/Update). */
function upsertCreditRequest(creditRequests, id, raw) {
  if (id == null) return creditRequests;
  const rest = creditRequests.filter((cr) => String(cr.id) !== String(id));
  return [...rest, { ...raw, id }];
}

// ---------------------------------------------------------------------------
// Pusher branch (updateFromPusher, U:1056-1452)
// ---------------------------------------------------------------------------

function reduceFromPusher(state, event, now, ownBidderNumbers) {
  switch (event.type) {
    case 'saleUpdate': {
      // U:1084-1110 — hold the closing lot on screen for 2s when the active
      // item changes; the hook schedules APPLY_PENDING_SALE_UPDATE. A newer
      // sale__update during the delay overwrites the parked one.
      const currentItem = state.sale ? state.sale.item : null;
      const isItemChanging = currentItem != null && currentItem !== event.data.item;
      if (isItemChanging) {
        return { ...state, pendingSaleUpdate: event.data };
      }
      return applySaleUpdate(state, event.data);
    }

    case 'itemUpdate': {
      // U:1112-1176 — merge the calculated payload; clear the optimistic
      // Going flag; heartbeat-reset a queued bid whose result never arrived.
      const items = insertCalculatedItems(state.items, [
        { uuid: event.uuid, calculated: event.calculated },
      ]);
      let queuedRequest = state.queuedRequest;
      if (
        queuedRequest.state === QUEUED.QUEUED &&
        queuedRequest.startTime != null &&
        now - queuedRequest.startTime > QUEUED_HEARTBEAT_MS
      ) {
        queuedRequest = emptyQueuedRequest();
      }
      return { ...state, items, asyncGoingItemStatus: false, queuedRequest };
    }

    case 'messageCreate': {
      // U:1178-1187 (public) + the Elm private-chat routing: private
      // messages live in their own slot and never enter the public stream.
      if (isPrivateMessage(event.message)) {
        if (state.privateMessagesState !== 'success') return state;
        return {
          ...state,
          privateMessages: addMessage(state.privateMessages, event.message),
          privateUnread:
            event.message.type === MESSAGE_TYPE.PRIVATE_BY_CLERK
              ? state.privateUnread + 1
              : state.privateUnread,
        };
      }
      if (state.messagesState !== 'success') return state;
      return { ...state, messages: addMessage(state.messages, event.message) };
    }

    case 'bidDelete': {
      // U:1189-1272
      const items = updateBidDict(state.items, event.itemId, event.bidKey, event.bid);

      const revokedType =
        event.deletionType === 'changed_to_floor'
          ? ALERT.OWN_BID_REVOKED_TO_FLOOR
          : ALERT.OWN_BID_REVOKED;
      const deletedBid = getBid(items, event.itemId, event.bidKey);
      const alert =
        deletedBid && isOwnBid(deletedBid, ownBidderNumbers)
          ? { at: now, type: revokedType, amount: event.bid.amount }
          : state.alert;

      // Plain deletes get no backend message__create — synthesize a stream
      // row (changed_to_floor does get one; don't duplicate it).
      let messages = state.messages;
      if (event.deletionType === 'delete' && state.messagesState === 'success') {
        messages = addMessage(
          messages,
          syntheticDeleteMessage(event.itemId, event.bidKey, now),
        );
      }

      return { ...state, items, alert, messages };
    }

    case 'bidUpdate':
      // U:1274-1282
      return {
        ...state,
        items: updateBidDict(state.items, event.itemId, event.bidKey, event.bid),
      };

    case 'bidderInfoUpdate':
      // U:1284-1291 — bidder info lives outside this reducer (DataCache);
      // the hook invalidates and refetches.
      return state;

    case 'creditRequestCreate':
    case 'creditRequestUpdate':
      // U:1298-1314
      return {
        ...state,
        creditRequests: upsertCreditRequest(state.creditRequests, event.id, event.raw),
      };

    case 'liveQueuePostExecute': {
      // U:1316-1440 — only a result whose task id matches the queued bid is
      // ours; everything else (other bidders' results, stale events) is noise
      // — EXCEPT possibly our own result racing ahead of the POST response,
      // so unmatched place-bid results are buffered for HANDLE_BID_PLACED_OK.
      const { queuedRequest } = state;
      if (queuedRequest.state !== QUEUED.QUEUED || queuedRequest.taskId !== event.taskId) {
        if (event.result.kind === 'other') {
          return state;
        }
        const recentLiveQueueResults = [
          ...state.recentLiveQueueResults,
          { taskId: event.taskId, result: event.result, at: now },
        ].slice(-10);
        return { ...state, recentLiveQueueResults };
      }

      // Remaining livequeue labels are clerk-only (U:1438-1440).
      if (event.result.kind === 'other') {
        return state;
      }
      return applyLiveQueueResult(state, event.result, now, ownBidderNumbers);
    }

    case 'clerkQueuedBidsUpdate':
      // U:1442-1446
      return {
        ...state,
        clerkHighestQueuedBidData: { bid: event.bid, nextBid: event.nextBid },
      };

    case 'clerkActiveToGoing':
      // U:1448-1452
      return { ...state, asyncGoingItemStatus: true };

    case 'forceReload':
      // JS-only event (Pusher/Model.elm eventNames comment); same effect as a
      // session change — the hook tears down and refetches everything.
      return { ...state, needsFullReload: true };

    default:
      return state;
  }
}

// ---------------------------------------------------------------------------
// Reducer
// ---------------------------------------------------------------------------

export function reducer(state, action) {
  switch (action.type) {
    case ACTIONS.SALE_FETCH_STARTED:
      // Subscribe (U:600-611) resets only the alert and the sale WebData.
      return { ...state, alert: null, saleState: 'loading', saleError: null };

    case ACTIONS.HANDLE_FETCHED_SALE_OK: {
      // U:242-271 — build the item manager from the lot map; reset the
      // bidder currency selector so a pick never leaks across sales.
      const items = itemManagerFromLotMap(action.lotMap);
      return {
        ...state,
        saleState: 'success',
        sale: action.sale,
        saleError: null,
        items,
        selectedCurrency: null,
        carouselPosition: calculateCarouselPosition(
          state.numberOfCarouselItems,
          action.sale.item,
          items,
        ),
      };
    }

    case ACTIONS.HANDLE_FETCHED_SALE_ERR:
      return { ...state, saleState: 'failure', saleError: action.error };

    case ACTIONS.HANDLE_FETCHED_SALE_TITLE: {
      // U:280-292 — the BS response has no translated title; the static JSON
      // does.
      if (state.saleState !== 'success') return state;
      return { ...state, sale: { ...state.sale, label: action.title } };
    }

    case ACTIONS.HANDLE_FETCHED_CURRENCIES_INFO: {
      // U:301-313
      if (state.saleState !== 'success') return state;
      return { ...state, sale: { ...state.sale, currenciesInfo: action.currenciesInfo } };
    }

    case ACTIONS.HANDLE_FETCHED_STATIC_ITEMS: {
      // Keep carouselPosition: statics now arrive on demand while the user
      // browses the filmstrip, and recentering here would snap the strip
      // back to the active lot on the very move that triggered the fetch
      // (same fix as the Elm MsgItemManager branch).
      const items = insertStaticItems(state.items, action.staticItems);
      return { ...state, items };
    }

    case ACTIONS.CALCULATED_ITEMS_LOADING:
      return {
        ...state,
        items: setCalculatedState(state.items, action.itemIds, CALC_STATE.LOADING),
      };

    case ACTIONS.HANDLE_FETCHED_CALCULATED_ITEMS_OK: {
      const items = insertCalculatedItems(state.items, action.entries);
      return { ...state, items, carouselPosition: recalcCarousel(state, items) };
    }

    case ACTIONS.HANDLE_FETCHED_CALCULATED_ITEMS_ERR:
      return {
        ...state,
        items: setCalculatedState(state.items, action.itemIds, CALC_STATE.FAILURE),
      };

    case ACTIONS.MESSAGES_LOADING:
      return { ...state, messagesState: 'loading' };

    case ACTIONS.HANDLE_FETCHED_MESSAGES_OK:
      // U:322-336 — the hook follows up with a calculated-items fetch for
      // messages.getItemsIds(action.messages).
      return { ...state, messagesState: 'success', messages: action.messages };

    case ACTIONS.HANDLE_FETCHED_MESSAGES_ERR:
      return { ...state, messagesState: 'failure' };

    case ACTIONS.PRIVATE_MESSAGES_LOADING:
      return { ...state, privateMessagesState: 'loading' };

    case ACTIONS.HANDLE_FETCHED_PRIVATE_MESSAGES_OK:
      return {
        ...state,
        privateMessagesState: 'success',
        privateMessages: action.messages,
      };

    case ACTIONS.HANDLE_FETCHED_PRIVATE_MESSAGES_ERR:
      return { ...state, privateMessagesState: 'failure' };

    case ACTIONS.PRIVATE_CHAT_SEEN:
      return { ...state, privateUnread: 0 };

    case ACTIONS.HANDLE_FETCHED_CREDIT_REQUESTS:
      return { ...state, creditRequests: action.creditRequests || [] };

    case ACTIONS.BID_AMOUNT_INCREMENT:
      // U:67-72 — push the concrete step amount.
      return { ...state, nextBidIncrements: [action.amount, ...state.nextBidIncrements] };

    case ACTIONS.BID_AMOUNT_DECREMENT:
      // U:74-79 — pop.
      return { ...state, nextBidIncrements: state.nextBidIncrements.slice(1) };

    case ACTIONS.PLACE_BID_SENT:
      // See the deviation note at the top of this file. startTime lets the
      // 15s timeout poll also rescue a POST that never resolves.
      return {
        ...state,
        queuedRequest: {
          ...emptyQueuedRequest(),
          state: QUEUED.SENT,
          startTime: action.now != null ? action.now : null,
        },
      };

    case ACTIONS.HANDLE_BID_PLACED_OK: {
      // U:202-218 — the POST answered with the livequeue task id; the real
      // outcome arrives via the livequeue__post_execute pusher event. If the
      // result ALREADY arrived (fast backend — pusher beat the HTTP
      // response), apply it from the buffer immediately.
      const buffered = state.recentLiveQueueResults.find(
        (entry) => entry.taskId === action.taskId,
      );
      const queued = {
        ...state,
        queuedRequest: {
          state: QUEUED.QUEUED,
          taskId: action.taskId,
          startTime: action.now,
          error: null,
        },
      };
      if (!buffered) {
        return queued;
      }
      return applyLiveQueueResult(
        {
          ...queued,
          recentLiveQueueResults: state.recentLiveQueueResults.filter(
            (entry) => entry !== buffered,
          ),
        },
        buffered.result,
        action.now,
        action.ownBidderNumbers || [],
      );
    }

    case ACTIONS.HANDLE_BID_PLACED_ERR:
      // U:220-229 — HTTP failure: clear the queued state AND the alert.
      return { ...state, queuedRequest: emptyQueuedRequest(), alert: null };

    case ACTIONS.CHECK_QUEUED_REQUEST_TIMEOUT: {
      // U:81-120 — poll: a queued bid with no result after 15s unlocks the
      // button (the livequeue event was lost). SENT is included so a POST
      // that never resolves can't lock the button forever (see deviation
      // note at the top of this file).
      const { queuedRequest } = state;
      if (
        (queuedRequest.state === QUEUED.QUEUED || queuedRequest.state === QUEUED.SENT) &&
        queuedRequest.startTime != null &&
        action.now - queuedRequest.startTime > QUEUED_REQUEST_TIMEOUT_MS
      ) {
        return { ...state, queuedRequest: emptyQueuedRequest() };
      }
      return state;
    }

    case ACTIONS.ITEMS_NEXT:
      // U:414-429 (popup-close side lives in components)
      return {
        ...state,
        ...closeAllPopups,
        carouselPosition: incrementItemSlider(state.items, state.carouselPosition),
      };

    case ACTIONS.ITEMS_PREVIOUS:
      // U:431-446
      return {
        ...state,
        ...closeAllPopups,
        carouselPosition: decrementItemSlider(state.items, state.carouselPosition),
      };

    case ACTIONS.SET_SELECTED_CURRENCY:
      // U:798-803 — null means "the sale's own currency".
      return { ...state, selectedCurrency: action.currency };

    case ACTIONS.APPLY_PENDING_SALE_UPDATE: {
      // U:812-823
      if (!state.pendingSaleUpdate) return state;
      const pending = state.pendingSaleUpdate;
      return applySaleUpdate({ ...state, pendingSaleUpdate: null }, pending);
    }

    case ACTIONS.PUSHER_EVENT: {
      // U:359-412 — every pusher event first re-evaluates the alert hold,
      // then applies its branch. Events are ignored until the sale is loaded
      // (Elm unwraps model.sale).
      if (state.saleState !== 'success') return state;
      const held = { ...state, alert: heldAlert(state, action.now) };
      return reduceFromPusher(held, action.event, action.now, action.ownBidderNumbers || []);
    }

    case ACTIONS.SALE_SYNCED:
      if (state.saleState !== 'success') return state;
      return applySaleUpdate(state, action.data);

    case ACTIONS.FULL_RELOAD_HANDLED:
      return { ...state, needsFullReload: false };

    default:
      return state;
  }
}
