import PusherModule from 'pusher-js';

// pusher-js's React Native dist (dist/react-native/pusher.js, selected via the
// package's "react-native" field) exports `module.exports.Pusher = …` — a
// NAMED export with no ESM default. The web/node dists export the constructor
// directly. Resolve the constructor across all interop shapes; init() guards
// against it being missing so realtime can never crash the app.
const Pusher =
  PusherModule?.Pusher ||
  PusherModule?.default?.Pusher ||
  (typeof PusherModule === 'function' ? PusherModule : PusherModule?.default);

/**
 * PusherService — real-time updates for Circuit Auction.
 *
 * Ported near-verbatim from web/src/services/PusherService.js. pusher-js runs
 * in React Native unchanged (it uses `fetch` + `URLSearchParams`, both present
 * in RN). Subscribes to:
 *   - public sale channel:  `sale-{saleUuid}`
 *   - private user channel: `private-user-{userUuid}`
 * Events: item__update, sale__update, bidder_info__update.
 * Channel auth: POST {backendUrl}/api/pusher_auth with the bs `access-token`.
 */
class PusherService {
  constructor() {
    this.pusher = null;
    this.channels = {};
    this.eventHandlers = {};
    this.isInitializing = false;
    this.initConfig = null;
    // Session token read at authorize-time (see setAccessToken) — a closure
    // capture here would freeze the first init()'s token forever.
    this.accessToken = null;
    // Per-channel set of already-bound event names, so bindChannelEvents()
    // can add events to an existing channel without double-binding.
    this.boundEvents = {};
    // Handlers for pusher connection state changes (offline indicator).
    this.connectionStateHandlers = [];
    // Ring buffer of recent incoming events/errors for the debug overlay.
    this.eventLog = [];
    this.eventLogHandlers = [];
  }

  _logEvent(entry) {
    this.eventLog.push({ at: Date.now(), ...entry });
    if (this.eventLog.length > 100) {
      this.eventLog.shift();
    }
    this.eventLogHandlers.forEach((handler) => handler(this.eventLog));
  }

  /** The recent-events ring buffer (newest last) — debug overlay food. */
  getEventLog() {
    return this.eventLog;
  }

  onEventLogged(handler) {
    this.eventLogHandlers.push(handler);
  }

  offEventLogged(handler) {
    this.eventLogHandlers = this.eventLogHandlers.filter((h) => h !== handler);
  }

  /**
   * Update the session token used for private-channel auth. init() calls this
   * too, INCLUDING on its idempotent early-return path — so a login that
   * happens after a tokenless init (e.g. DataCache initializing pre-login)
   * still authorizes private channels without an app restart.
   */
  setAccessToken(token) {
    this.accessToken = token || null;
  }

  init(config) {
    if (config && 'accessToken' in config) {
      this.setAccessToken(config.accessToken);
    }
    if (this.pusher && this.initConfig) {
      const isSameConfig =
        this.initConfig.key === config.key &&
        this.initConfig.cluster === config.cluster &&
        this.initConfig.authEndpoint === config.authEndpoint;
      if (isSameConfig) {
        return;
      }
    }
    if (this.pusher) {
      console.warn('[PusherService] already initialized with different config');
      return;
    }
    if (this.isInitializing) {
      return;
    }

    if (typeof Pusher !== 'function') {
      console.error('[PusherService] pusher-js constructor not found — realtime disabled');
      return;
    }

    this.isInitializing = true;
    const { key, cluster, authEndpoint, accessToken } = config;
    this.initConfig = { key, cluster, authEndpoint };

    // Pusher only accepts lowercase cluster identifiers (EuWest1 -> eu, etc.).
    const normalizedCluster = cluster
      .toLowerCase()
      .replace(/west1?|east1?/i, '');

    this.pusher = new Pusher(key, {
      cluster: normalizedCluster,
      authEndpoint,
      auth: {
        params: { access_token: accessToken },
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      },
      // Custom authorizer to match the backend's { auth: "key:sig" } response.
      // IMPORTANT: the backend authenticates this endpoint via the
      // access_token QUERY PARAM (the Elm app builds authEndpoint as
      // "/api/pusher_auth?access_token=…" — Pusher/Update.elm:49); the
      // access-token header alone gets a 401 and private channels never
      // subscribe (which silently kills livequeue bid results).
      authorizer: (channel) => ({
        authorize: (socketId, callback) => {
          const formData = new URLSearchParams();
          formData.append('socket_id', socketId);
          formData.append('channel_name', channel.name);
          const sep = authEndpoint.includes('?') ? '&' : '?';
          // Read the token from the instance at authorize-time, NOT the init()
          // closure — the token may have been set/refreshed since init.
          const token = this.accessToken;
          const authUrl = `${authEndpoint}${sep}access_token=${encodeURIComponent(token || '')}`;
          fetch(authUrl, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded',
              'access-token': token,
            },
            body: formData.toString(),
          })
            .then((response) => {
              if (!response.ok) {
                throw new Error(`Auth failed with status ${response.status}`);
              }
              return response.json();
            })
            .then((data) => callback(null, { auth: data.auth }))
            .catch((error) => {
              console.error('Pusher auth error:', error);
              this._logEvent({ kind: 'error', event: 'auth_error', detail: `${channel.name}: ${error.message}` });
              callback(error, null);
            });
        },
      }),
      forceTLS: true,
    });

    this.pusher.connection.bind('connected', () => {
      this.isInitializing = false;
    });
    this.pusher.connection.bind('error', (err) => {
      console.error('Pusher connection error:', err);
      this.isInitializing = false;
    });
    this.pusher.connection.bind('state_change', (states) => {
      this._logEvent({
        kind: 'connection',
        event: 'state_change',
        detail: `${states?.previous} -> ${states?.current}`,
      });
      this.connectionStateHandlers.forEach((handler) => handler(states));
    });
  }

  /**
   * Subscribe to connection state changes ({ previous, current } — current is
   * one of pusher-js's 'connected' | 'connecting' | 'unavailable' | ...).
   * Drives the live sale page's offline banner. Safe to call before init().
   */
  onConnectionStateChange(handler) {
    this.connectionStateHandlers.push(handler);
  }

  offConnectionStateChange(handler) {
    this.connectionStateHandlers = this.connectionStateHandlers.filter(
      (h) => h !== handler,
    );
  }

  subscribe(saleUuid, userUuid = null) {
    if (!this.pusher) {
      console.error('Pusher not initialized');
      return;
    }
    const publicChannelName = `sale-${saleUuid}`;
    if (!this.channels[publicChannelName]) {
      this.channels[publicChannelName] = this.pusher.subscribe(publicChannelName);
      this._bindChannelEvents(this.channels[publicChannelName], 'public');
    }
    if (userUuid) {
      const privateChannelName = `private-user-${userUuid}`;
      if (!this.channels[privateChannelName]) {
        this.channels[privateChannelName] =
          this.pusher.subscribe(privateChannelName);
        this._bindChannelEvents(this.channels[privateChannelName], 'private');
      }
    }
  }

  _bindChannelEvents(channel, channelType) {
    const eventNames = ['item__update', 'sale__update', 'bidder_info__update'];
    this._trackAndBind(channel, eventNames, channelType);
    channel.bind('pusher:subscription_error', (status) => {
      console.error(`Subscription error for ${channelType} ${channel.name}:`, status);
    });
  }

  _trackAndBind(channel, eventNames, channelType) {
    if (!this.boundEvents[channel.name]) {
      this.boundEvents[channel.name] = new Set();
      channel.bind('pusher:subscription_succeeded', () => {
        this._logEvent({ kind: 'channel', event: 'subscribed', detail: channel.name });
      });
      channel.bind('pusher:subscription_error', (status) => {
        this._logEvent({
          kind: 'error',
          event: 'subscription_error',
          detail: `${channel.name}: ${JSON.stringify(status)?.slice(0, 80)}`,
        });
      });
    }
    const bound = this.boundEvents[channel.name];
    eventNames.forEach((eventName) => {
      if (bound.has(eventName)) {
        return;
      }
      bound.add(eventName);
      channel.bind(eventName, (data) => {
        this._logEvent({ kind: 'event', event: eventName, detail: channel.name });
        if (this.eventHandlers[eventName]) {
          // Third arg lets multi-channel subscribers (clerk feed) attribute an
          // event to its channel — e.g. sale__update carries no sale id.
          this.eventHandlers[eventName].forEach((handler) =>
            handler(data, channelType, channel.name),
          );
        }
      });
    });
  }

  /**
   * Bind additional event names to an ALREADY-SUBSCRIBED channel. Needed by
   * the live sale screen: subscribe()/subscribeChannel() early-return when
   * the channel exists (e.g. PlaceBid already subscribed `sale-<uuid>` with
   * the default trio), so extra live events must be bindable after the fact.
   * Already-bound names are skipped, so calling this repeatedly is safe.
   */
  bindChannelEvents(channelName, eventNames) {
    const channel = this.channels[channelName];
    if (!this.pusher || !channel) {
      return;
    }
    this._trackAndBind(channel, eventNames);
  }

  subscribeChannel(channelName, eventNames) {
    if (!this.pusher || this.channels[channelName]) {
      return;
    }
    const channel = this.pusher.subscribe(channelName);
    this.channels[channelName] = channel;
    this._trackAndBind(channel, eventNames);
  }

  unsubscribeChannel(channelName) {
    if (!this.pusher || !this.channels[channelName]) {
      return;
    }
    this.pusher.unsubscribe(channelName);
    delete this.channels[channelName];
    delete this.boundEvents[channelName];
  }

  on(eventName, handler) {
    if (!this.eventHandlers[eventName]) {
      this.eventHandlers[eventName] = [];
    }
    this.eventHandlers[eventName].push(handler);
  }

  off(eventName, handler) {
    if (this.eventHandlers[eventName]) {
      this.eventHandlers[eventName] = this.eventHandlers[eventName].filter(
        (h) => h !== handler,
      );
    }
  }

  /**
   * Remove EVERY channel — including the DataCache `invalidation-cache-*`
   * channel. Screens must tear down with targeted unsubscribeChannel()
   * calls instead; this is only for logout/full shutdown.
   */
  unsubscribe() {
    if (!this.pusher) {
      return;
    }
    Object.keys(this.channels).forEach((channelName) =>
      this.pusher.unsubscribe(channelName),
    );
    this.channels = {};
    this.boundEvents = {};
  }

  disconnect() {
    if (this.pusher) {
      this.unsubscribe();
      this.pusher.disconnect();
      this.pusher = null;
    }
    this.eventHandlers = {};
    this.connectionStateHandlers = [];
  }
}

const pusherService = new PusherService();
export { PusherService };
export default pusherService;
