// common/domain/liveSale/saleModel.js
//
// Pure normalization of the live-sale entity — a React implementation of the
// Elm bidder live-auction page ("Pages/Sale") from the circuit-bid client.
//
// SOURCE OF TRUTH (Elm, circuit-bid/client/src/elm):
//   - Sale/Model.elm        -> Sale / SaleUpdateData / Status shapes
//   - Sale/Decoder.elm      -> normalizeSale / normalizeSaleUpdate /
//                              normalizeAutoClerk / currenciesInfoFromBatch
//   - Sale/Utils.elm        -> getActiveSession / constructPublicUrls /
//                              getRoundAndBumpTimeFromAutoClerk
//
// The wire format is the bid-server GET /api/sales/<uuid>?loadByFieldName=uuid
// response (data[0]) and the pusher `sale__update` payload. All amounts are
// plain integers; statuses keep the raw server strings.
//
// This module is pure: no network, no React, no i18n.

/** Sale statuses as returned by the server (Sale/Decoder.elm decodeStatus). */
export const SALE_STATUS = {
  CLOSED_NOT_STARTED: 'closed_not_started',
  MAIL_AUCTION_OPEN: 'open_mail',
  PAUSED_STARTING_SOON: 'paused_starting_soon',
  LIVE_AUCTION_OPEN: 'open_live',
  PAUSED_BACK_SHORTLY: 'paused_back_shortly',
  CLOSED_ENDED: 'closed_ended',
};

const KNOWN_STATUSES = Object.values(SALE_STATUS);

export function isKnownSaleStatus(status) {
  return KNOWN_STATUSES.includes(status);
}

/** True when the live auction is running (bids possible). */
export function isLiveAuctionOpen(sale) {
  return sale?.status === SALE_STATUS.LIVE_AUCTION_OPEN;
}

/**
 * The sale states where the bidder page shows an overlay instead of the live
 * lot view (Pages/Sale/View.elm itemViewOverlay / salePaused): everything
 * except an open live auction.
 */
export function salePaused(sale) {
  return sale != null && sale.status !== SALE_STATUS.LIVE_AUCTION_OPEN;
}

/**
 * AutoClerk normalization (Sale/Decoder.elm decodeAutoClerk):
 *   { auto_clerk_enabled, auto_clerk_round, auto_clerk_bump }
 * -> { round: <seconds>, bump: <seconds> } when enabled, else null
 * (null mirrors Elm's AutoClerkDisabled; getRoundAndBumpTimeFromAutoClerk is
 * then just a null check on the caller side).
 */
export function normalizeAutoClerk(raw) {
  if (!raw || !raw.auto_clerk_enabled) return null;
  return {
    round: parseInt(raw.auto_clerk_round) || 0,
    bump: parseInt(raw.auto_clerk_bump) || 0,
  };
}

/**
 * Session normalization (Backend/Session/Decoder.elm decodeSession).
 * Wire: [{ id, label, first_item, last_item, delta, item_count }]
 * -> ordered array of { id, label, firstItem, lastItem, delta, itemCount }.
 */
export function normalizeSessions(rawSessions) {
  if (!Array.isArray(rawSessions)) return [];
  return rawSessions.map((s) => ({
    id: parseInt(s.id),
    label: s.label || '',
    firstItem: parseInt(s.first_item) || 0,
    lastItem: parseInt(s.last_item) || 0,
    delta: parseInt(s.delta) || 0,
    itemCount: parseInt(s.item_count) || 0,
  }));
}

/**
 * Sale normalization (Sale/Decoder.elm decodeSale). `raw` is the data[0]
 * element of the GET /api/sales/<uuid> response.
 *
 * `currenciesInfo` starts empty (Elm hardcodes EveryDict.empty) — it is
 * populated later from the sale-level extras riding on the items-json
 * responses (currenciesInfoFromBatch).
 */
export function normalizeSale(raw) {
  if (!raw) return null;
  return {
    id: parseInt(raw.id),
    label: raw.label || '',
    status: raw.status,
    // The active lot (numeric item id).
    item: parseInt(raw.item) || 0,
    // Active session id ("session" is optional until re-sync — Decoder.elm:80).
    session: raw.session != null ? parseInt(raw.session) : 0,
    sessions: normalizeSessions(raw.sessions),
    languages: Array.isArray(raw.language) ? raw.language : [],
    // Synced display-currency rates; items-json responses refresh them too.
    currenciesInfo: currenciesInfoFromBatch({ currenciesInfo: raw.currencies_info }),
    liveAuctionStart: raw.live_auction_start || null,
    siteLabel: raw.site_label || '',
    siteLogoUrl: raw.site_logo_url || '',
    siteBackofficeUrl: raw.site_backoffice_url || '',
    currentTime: raw.current_time || null,
    currency: raw.currency,
    uuid: raw.uuid,
    videoStream: raw.video_stream || null,
    websiteRangeStart: parseInt(raw.website_range_start) || 0,
    websiteRangeEnd: parseInt(raw.website_range_end) || 0,
    pausedMessage: raw.paused_message || '',
    autoClerk: normalizeAutoClerk(raw),
    // { [currencyCode]: rate } — filled from the static JSON batches.
  };
}

/**
 * Pusher `sale__update` payload normalization (Sale/Decoder.elm
 * decodeSaleUpdate). NOTE the payload carries the label under `title`,
 * not `label`.
 */
export function normalizeSaleUpdate(raw) {
  if (!raw) return null;
  return {
    label: raw.title || '',
    status: raw.status,
    autoClerk: normalizeAutoClerk(raw),
    pausedMessage: raw.paused_message || '',
    item: parseInt(raw.item) || 0,
    session: raw.session != null ? parseInt(raw.session) : 0,
    // The public message-stream clear point (0 = never cleared).
    messageClearId: parseInt(raw.message_clear_id) || 0,
    // Rates riding the broadcast — empty may just mean an older bid
    // server, so appliers keep their current rates then.
    currenciesInfo: currenciesInfoFromBatch({ currenciesInfo: raw.currencies_info }),
  };
}

/**
 * Lot-map normalization (ItemManager/Decoder.elm decodeLotMapDict). The
 * /api/sales response carries `lots`: [{ uuid, lot, item_id }] in lot order.
 * -> ordered array of { uuid, lotId, itemId }.
 */
export function normalizeLotMap(rawLots) {
  if (!Array.isArray(rawLots)) return [];
  return rawLots.map((l) => ({
    uuid: l.uuid,
    lotId: l.lot || '',
    itemId: parseInt(l.item_id) || 0,
  }));
}

/** The active session record, or null (Sale/Utils.elm getActiveSession). */
export function getActiveSession(sale) {
  if (!sale) return null;
  return sale.sessions.find((s) => s.id === sale.session) || null;
}

/**
 * Sale title from a static batch JSON (Sale/Decoder.elm
 * decodeSaleTitleFromJson). Returns null when absent.
 */
export function saleTitleFromBatch(batchJson) {
  const title = batchJson?.sale_title;
  return typeof title === 'string' ? title : null;
}

/**
 * Exchange-rate table from a static batch JSON (Sale/Decoder.elm
 * decodeCurrenciesInfoFromJson): [{ currency, rate }] -> { CODE: rate }.
 * Missing/malformed input yields {} (the Elm decoder's `succeed empty`
 * fallback).
 */
export function currenciesInfoFromBatch(batchJson) {
  const list = batchJson?.currenciesInfo;
  if (!Array.isArray(list)) return {};
  const info = {};
  list.forEach((entry) => {
    if (entry && entry.currency != null) {
      const rate = parseFloat(entry.rate);
      if (!Number.isNaN(rate)) {
        info[entry.currency] = rate;
      }
    }
  });
  return info;
}
