/**
 * Shared i18next instance for the native app. The web app loads locale JSON
 * over HTTP (i18next-http-backend); React Native bundles the catalogs directly
 * and detects the device language via react-native-localize.
 *
 * The six catalogs in ./locales are the SINGLE SOURCE OF TRUTH for both apps.
 * The web app copies them into web/src/locales via `npm run sync-locales`
 * (runs automatically before web start/build). Keep languages complete and
 * placeholder-consistent with `npm run i18n:sync` (from native/), which runs
 * ../common/i18n/sync-translations.js. Default namespace: `translation`.
 */
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import * as RNLocalize from 'react-native-localize';

import en from './locales/en.json';
import fr from './locales/fr.json';
import de from './locales/de.json';
import nl from './locales/nl.json';
import ru from './locales/ru.json';
import zh from './locales/zh.json';

export const SUPPORTED_LANGUAGES = ['en', 'fr', 'de', 'nl', 'ru', 'zh'];

const resources = {
  en: { translation: en },
  fr: { translation: fr },
  de: { translation: de },
  nl: { translation: nl },
  ru: { translation: ru },
  zh: { translation: zh },
};

const detectLanguage = () => {
  const best = RNLocalize.findBestLanguageTag(SUPPORTED_LANGUAGES);
  return best?.languageTag || 'en';
};

if (!i18n.isInitialized) {
  i18n.use(initReactI18next).init({
    resources,
    lng: detectLanguage(),
    fallbackLng: 'en',
    supportedLngs: SUPPORTED_LANGUAGES,
    interpolation: { escapeValue: false },
    returnNull: false,
  });
}

/**
 * Current UI language code. Used by the DataCache for per-language cache
 * namespacing (a zh payload must never satisfy an en read) and by API calls
 * that take a `language` param.
 */
export const getLanguage = () => i18n.language || 'en';

export default i18n;
