// common/domain/liveSale/items.js
//
// Pure item/bid normalization and the item-manager merge rules for the live
// sale page — a React implementation of the Elm bidder live-auction page.
//
// SOURCE OF TRUTH (Elm, circuit-bid/client/src/elm):
//   - Item/Model.elm         -> Item / CalculatedItem / Status shapes
//   - Item/Decoder.elm       -> normalizeCalculatedItem / normalizeStaticItem /
//                               normalizeItemStatus / normalizeItemAutoClerk
//   - Bid/Decoder.elm        -> normalizeBid / normalizeBidDict
//   - Bid/Utils.elm          -> bid status helpers / getHighestBid / isOwnBid
//   - Item/Utils.elm         -> getPrice / hasWinningBid / status helpers
//   - ItemManager/Model.elm  -> the { items, order } manager shape
//   - ItemManager/Utils.elm  -> emptyItemManagerFromLotMap / insertStaticItems /
//                               insertCalculatedItems / updateBidDict /
//                               getCurrentAndNextItemIds
//
// An "item manager" here is:
//   {
//     order: [itemId, ...]                    // lot order (EveryDictList order)
//     byId:  { [itemId]: Item }
//   }
// where Item is:
//   {
//     itemId, uuid, lotId,
//     name, image, galleryImages, description, estimatedPrice, estimatedLow,
//     estimatedHigh, openingPrice, subtitle, webUrl,        // static (S3)
//     calculated: CalculatedItem | null,
//     calculatedState: 'notAsked' | 'loading' | 'success' | 'failure',
//   }
//
// This module is pure: no network, no React, no i18n.

// ---------------------------------------------------------------------------
// Item status
// ---------------------------------------------------------------------------

/**
 * Flat item statuses. Ports Elm's nested Status type (Item/Model.elm):
 *   EditableStatus (LiveOnly Open|Going|Paused) -> 'open' | 'going' | 'paused'
 *   EditableStatus MailOnly                     -> 'mail_only'
 *   ReadOnlyStatus (ItemClosed Sold|Unsold)     -> 'sold' | 'unsold'
 *   ReadOnlyStatus SaleNotStarted               -> 'sale_not_started'
 *   ReadOnlyStatus Withdrawn                    -> 'withdrawn'
 *   ReadOnlyStatus ItemNotActiveButAlreadyHasLiveBids -> 'not_active'
 */
export const ITEM_STATUS = {
  OPEN: 'open',
  GOING: 'going',
  PAUSED: 'paused',
  MAIL_ONLY: 'mail_only',
  SOLD: 'sold',
  UNSOLD: 'unsold',
  SALE_NOT_STARTED: 'sale_not_started',
  WITHDRAWN: 'withdrawn',
  NOT_ACTIVE: 'not_active',
};

/**
 * Item status from the calculated payload (Item/Decoder.elm decodeStatus):
 * branches on `availability_status`, falling through to `status` for the
 * live clerk state (open/going/paused) or the closed sold/unsold outcome.
 * Unknown combinations return null (the Elm decoder fails; we keep the item
 * without a status rather than dropping the whole payload).
 */
export function normalizeItemStatus(raw) {
  if (!raw) return null;
  const availability = raw.availability_status;
  const status = raw.status;

  const closed = () => {
    if (status === 'sold') return ITEM_STATUS.SOLD;
    if (status === 'unsold') return ITEM_STATUS.UNSOLD;
    return null;
  };

  switch (availability) {
    case 'live_only':
    case 'item_paused':
      if (status === 'open') return ITEM_STATUS.OPEN;
      if (status === 'going') return ITEM_STATUS.GOING;
      if (status === 'paused') return ITEM_STATUS.PAUSED;
      return null;
    case 'mail_only':
      return ITEM_STATUS.MAIL_ONLY;
    case 'sale_not_started':
      return ITEM_STATUS.SALE_NOT_STARTED;
    case 'sale_closed':
    case 'item_closed':
      return closed();
    case 'item_withdrawn':
      return ITEM_STATUS.WITHDRAWN;
    case 'none':
      return ITEM_STATUS.NOT_ACTIVE;
    default:
      return null;
  }
}

/** Live bidding possible on the lot (Item/Utils.elm isOpenOrGoing). */
export function isOpenOrGoing(status) {
  return status === ITEM_STATUS.OPEN || status === ITEM_STATUS.GOING;
}

/** The lot reached a final closed state (Item/Utils.elm isClosed). */
export function isItemClosed(status) {
  return status === ITEM_STATUS.SOLD || status === ITEM_STATUS.UNSOLD;
}

// ---------------------------------------------------------------------------
// Bids
// ---------------------------------------------------------------------------

/**
 * Bid statuses (Bid/Decoder.elm decodeBidStatus). Raw server values are kept,
 * with the two aliasing rules from the decoder applied:
 *   rejected_bidder_corrected  -> rejected
 *   accepted_delete_by_group   -> outbid
 */
export const LIVE_BID_STATUS = {
  ACCEPTED: 'accepted',
  ACCEPTED_DUPLICATED_AMOUNT: 'accepted_duplicated_amount',
  REJECTED: 'rejected',
  REJECTED_BIDDER_MAX: 'rejected_over_bidder_max',
  REJECTED_CREDIT_LIMIT: 'rejected_over_credit_limit',
  REJECTED_MAIL_AFTER_LAST_FLOOR: 'rejected_mail_after_last_floor',
  REJECTED_BELOW_MINIMUM: 'rejected_bellow_minimum', // (sic — server spelling)
  OUTBID: 'outbid',
};

function normalizeBidStatus(status) {
  if (status === 'rejected_bidder_corrected') return LIVE_BID_STATUS.REJECTED;
  if (status === 'accepted_delete_by_group') return LIVE_BID_STATUS.OUTBID;
  return status;
}

/**
 * Bid normalization, non-privileged variant (Bid/Decoder.elm decodeBid —
 * bidders read the `deleted` bool, and `bidder_id` may be absent on other
 * people's bids).
 */
export function normalizeBid(raw) {
  if (!raw) return null;
  return {
    amount: parseInt(raw.amount) || 0,
    status: normalizeBidStatus(raw.status),
    bidderNumber: raw.bidder_id != null ? parseInt(raw.bidder_id) : null,
    deleted: !!raw.deleted,
    type: raw.type || null,
    // Origin mail-bid id carried by `type: "book"` auto bids
    // (Bid/Decoder.elm 82-85 also reads `triggering_bid`; not needed here).
    mailBidKey: raw.mail_bid != null ? String(raw.mail_bid) : null,
    created: raw.created || null,
    changed: raw.changed || null,
    underExtension: !!raw.under_extension,
  };
}

/**
 * A bid list -> { [bidKey]: bid } map (Bid/Decoder.elm decodeBidDict; the
 * key is the bid's `id` as a string).
 */
export function normalizeBidDict(rawList) {
  const dict = {};
  if (!Array.isArray(rawList)) return dict;
  rawList.forEach((raw) => {
    if (raw && raw.id != null) {
      dict[String(raw.id)] = normalizeBid(raw);
    }
  });
  return dict;
}

/** Accepted and not deleted (Bid/Utils.elm isValid). */
export function isValidBid(bid) {
  return !!bid && bid.status === LIVE_BID_STATUS.ACCEPTED && !bid.deleted;
}

/**
 * Bid ownership for a (non-privileged) bidder: the bid's bidder number is one
 * of the user's own bidder numbers for this sale (Bid/Utils.elm isOwnBid,
 * non-privileged branch: `Dict.member number modelBackend.bidderInfoByBidderNumber`).
 *
 * @param {object} bid            Normalized bid.
 * @param {number[]} ownBidderNumbers  The user's bidder numbers for the sale
 *   (from /api/bidder_ids records' `bidder_number`).
 */
export function isOwnBid(bid, ownBidderNumbers) {
  if (!bid || bid.bidderNumber == null) return false;
  return (ownBidderNumbers || []).includes(bid.bidderNumber);
}

/**
 * Is the user the current winner of the lot (Item/Utils.elm isWinningUser)?
 * Resolves the server-flagged winningBid key against the live and book bid
 * dicts and checks validity + ownership.
 */
export function isWinningUser(calculated, ownBidderNumbers) {
  if (!calculated || calculated.winningBid == null) return false;
  const bid =
    calculated.bids?.[calculated.winningBid] ||
    calculated.bookBids?.[calculated.winningBid] ||
    null;
  return isValidBid(bid) && isOwnBid(bid, ownBidderNumbers);
}

/** Highest valid bid in a bid dict, or null (Bid/Utils.elm getHighestBid). */
export function getHighestBid(bidDict) {
  let highest = null;
  Object.keys(bidDict || {}).forEach((key) => {
    const bid = bidDict[key];
    if (isValidBid(bid) && (!highest || bid.amount > highest.bid.amount)) {
      highest = { key, bid };
    }
  });
  return highest;
}

/**
 * The user's highest bid across the live and book bid dicts, for the bid
 * history table (Bid/Utils.elm getOwnHighestMailOrLiveBid over
 * getOwnValidOrAmountDuplicatedBids — accepted OR accepted_duplicated_amount,
 * not deleted).
 * @returns {?object} The bid, or null when the user has none on the lot.
 */
export function getOwnHighestBid(calculated, ownBidderNumbers) {
  let highest = null;
  const consider = (bid) => {
    const validEnough =
      !!bid &&
      !bid.deleted &&
      (bid.status === LIVE_BID_STATUS.ACCEPTED ||
        bid.status === LIVE_BID_STATUS.ACCEPTED_DUPLICATED_AMOUNT);
    if (validEnough && isOwnBid(bid, ownBidderNumbers)) {
      if (!highest || bid.amount > highest.amount) {
        highest = bid;
      }
    }
  };
  Object.values(calculated?.bids || {}).forEach(consider);
  Object.values(calculated?.bookBids || {}).forEach(consider);
  return highest;
}

/**
 * The user's own mail (max) bid that currently holds the winning position
 * (Bid/Utils.elm getOwnWinningMailBid). Either the winning bid is the mail
 * bid itself in `bookBids`, or it is an auto `book`-type live bid executed
 * from the user's mail bid — resolve its `mailBidKey` back into `bookBids`,
 * falling back to the user's highest valid book bid when the key is absent.
 * @returns {?object} The mail bid (its `amount` is the user's max), or null
 *   when the user is not winning via a mail bid.
 */
export function getOwnWinningMailBid(calculated, ownBidderNumbers) {
  if (!calculated || calculated.winningBid == null) return null;
  const own = (bid) => isValidBid(bid) && isOwnBid(bid, ownBidderNumbers);

  const direct = calculated.bookBids?.[calculated.winningBid];
  if (direct) return own(direct) ? direct : null;

  const liveBid = calculated.bids?.[calculated.winningBid];
  if (!own(liveBid) || liveBid.type !== 'book') return null;

  if (liveBid.mailBidKey != null && calculated.bookBids?.[liveBid.mailBidKey]) {
    return calculated.bookBids[liveBid.mailBidKey];
  }
  let highest = null;
  Object.values(calculated.bookBids || {}).forEach((bid) => {
    if (own(bid) && (!highest || bid.amount > highest.amount)) {
      highest = bid;
    }
  });
  return highest;
}

// ---------------------------------------------------------------------------
// Calculated / static item normalization
// ---------------------------------------------------------------------------

/**
 * Per-item auto-clerk countdown (Item/Decoder.elm decodeAutoClerk). The
 * server sends its own clock plus the round/bump end timestamp; we convert to
 * a client-clock end time so the UI can render a countdown that is immune to
 * clock skew:  endsAt = now + (serverEnd - serverNow).
 * Timestamps are unix SECONDS on the wire; endsAt is client ms.
 * Returns { kind: 'round'|'bump', endsAt } or null.
 */
export function normalizeItemAutoClerk(raw, nowMs) {
  const autoClerk = raw?.auto_clerk;
  if (!autoClerk || autoClerk.current_timestamp == null) return null;
  const serverNow = parseInt(autoClerk.current_timestamp) || 0;
  const toEndsAt = (serverEnd) => nowMs + (parseInt(serverEnd) - serverNow) * 1000;
  if (autoClerk.round_timestamp != null) {
    return { kind: 'round', endsAt: toEndsAt(autoClerk.round_timestamp) };
  }
  if (autoClerk.bump_timestamp != null) {
    return { kind: 'bump', endsAt: toEndsAt(autoClerk.bump_timestamp) };
  }
  return null;
}

/**
 * Calculated item normalization (Item/Decoder.elm decodeCalculatedItem).
 * `raw` is one element of the /api/items response `data` array, or the pusher
 * `item__update` payload.
 *
 * @param {object} raw
 * @param {number} nowMs  Client clock, for the auto-clerk skew adjustment.
 */
export function normalizeCalculatedItem(raw, nowMs) {
  if (!raw) return null;
  return {
    startingPrice: parseInt(raw.starting_price) || 0,
    openingPrice: parseInt(raw.opening_price) || 0,
    currentPrice: raw.current_price != null ? parseInt(raw.current_price) : null,
    nextPrice: raw.next_price != null ? parseInt(raw.next_price) : null,
    status: normalizeItemStatus(raw),
    note: raw.note || null,
    publicMessage: raw.public_message || null,
    // Step grid: [{ from, amount, type }] with integer values.
    bidSteps: (Array.isArray(raw.steps) ? raw.steps : []).map((s) => ({
      from: parseInt(s.from) || 0,
      amount: parseInt(s.amount) || 0,
      type: s.type || 'regular',
    })),
    bids: normalizeBidDict(raw.bid),
    bookBids: normalizeBidDict(raw.book_bid),
    agentBids: normalizeBidDict(raw.agent_bid),
    minimumPrice: raw.minimum_price != null ? parseInt(raw.minimum_price) : null,
    winningBid: raw.winning_bid != null ? String(raw.winning_bid) : null,
    winningUserTotalWon:
      raw.winning_user_total_won != null ? parseInt(raw.winning_user_total_won) : null,
    autoClerk: normalizeItemAutoClerk(raw, nowMs),
    futureBookBidAmounts: (Array.isArray(raw.future_book_bid_amounts)
      ? raw.future_book_bid_amounts
      : []
    ).map((a) => parseInt(a) || 0),
  };
}

/** Placeholder shown when the backend supplies no image (Item/Decoder.elm). */
export const DEFAULT_ITEM_IMAGE =
  'https://s3.eu-central-1.amazonaws.com/circuit-bid/default-image.png';

/** Image style (Item/Decoder.elm decodeImageStyle). */
export function normalizeImageStyle(raw) {
  const original = raw?.image || DEFAULT_ITEM_IMAGE;
  return {
    original,
    big: raw?.imageBig || raw?.image || DEFAULT_ITEM_IMAGE,
    small: raw?.imageSmall || DEFAULT_ITEM_IMAGE,
  };
}

/**
 * Static item normalization from the S3 batch JSON (Item/Decoder.elm
 * decodeStaticItem; the batch carries `items`: [{ uuid, title, image,
 * imageBig, imageSmall, galleryImages, body, estimatedPrice, estimatedlow,
 * estimatedHigh, startPrice, subtitle, item_web_url }]).
 */
export function normalizeStaticItem(raw) {
  if (!raw) return null;
  return {
    uuid: raw.uuid,
    name: raw.title || '',
    image: normalizeImageStyle(raw),
    galleryImages: (Array.isArray(raw.galleryImages) ? raw.galleryImages : []).map(
      normalizeImageStyle,
    ),
    description: raw.body || null,
    estimatedPrice: raw.estimatedPrice != null ? parseInt(raw.estimatedPrice) : null,
    // (sic — the wire really is lowercase "estimatedlow", Item/Decoder.elm:35)
    estimatedLow: raw.estimatedlow != null ? parseInt(raw.estimatedlow) : null,
    estimatedHigh: raw.estimatedHigh != null ? parseInt(raw.estimatedHigh) : null,
    openingPrice: raw.startPrice != null ? parseInt(raw.startPrice) : null,
    subtitle: raw.subtitle || null,
    webUrl: raw.item_web_url || null,
  };
}

// ---------------------------------------------------------------------------
// Item manager (ItemManager/Model.elm + Utils.elm)
// ---------------------------------------------------------------------------

export const CALC_STATE = {
  NOT_ASKED: 'notAsked',
  LOADING: 'loading',
  SUCCESS: 'success',
  FAILURE: 'failure',
};

/**
 * Build the partial item manager from the lot map (ItemManager/Utils.elm
 * emptyItemManagerFromLotMap). Static/calculated fields start empty and are
 * populated by insertStaticItems / insertCalculatedItems.
 *
 * @param {Array<{uuid, lotId, itemId}>} lotMap  From saleModel.normalizeLotMap.
 */
export function itemManagerFromLotMap(lotMap) {
  const byId = {};
  const order = [];
  (lotMap || []).forEach((lot) => {
    order.push(lot.itemId);
    byId[lot.itemId] = {
      itemId: lot.itemId,
      uuid: lot.uuid,
      lotId: lot.lotId,
      name: '',
      image: null,
      galleryImages: [],
      description: null,
      estimatedPrice: null,
      estimatedLow: null,
      estimatedHigh: null,
      openingPrice: null,
      subtitle: null,
      webUrl: null,
      calculated: null,
      calculatedState: CALC_STATE.NOT_ASKED,
    };
  });
  return { order, byId };
}

export const emptyItemManager = () => ({ order: [], byId: {} });

/** uuid -> itemId lookup built from the manager itself. */
function itemIdByUuid(manager, uuid) {
  const found = manager.order.find((id) => manager.byId[id]?.uuid === uuid);
  return found != null ? found : null;
}

/**
 * Merge a batch of static items into the manager (ItemManager/Utils.elm
 * insertStaticItems). Unknown uuids are ignored.
 */
export function insertStaticItems(manager, staticItems) {
  if (!staticItems || staticItems.length === 0) return manager;
  const byId = { ...manager.byId };
  let changed = false;
  staticItems.forEach((staticItem) => {
    if (!staticItem) return;
    const itemId = itemIdByUuid(manager, staticItem.uuid);
    if (itemId == null) return;
    const item = byId[itemId];
    byId[itemId] = {
      ...item,
      name: staticItem.name,
      image: staticItem.image,
      galleryImages: staticItem.galleryImages,
      description: staticItem.description,
      estimatedPrice: staticItem.estimatedPrice,
      estimatedLow: staticItem.estimatedLow,
      estimatedHigh: staticItem.estimatedHigh,
      openingPrice: staticItem.openingPrice,
      subtitle: staticItem.subtitle,
      webUrl: staticItem.webUrl,
    };
    changed = true;
  });
  return changed ? { ...manager, byId } : manager;
}

/**
 * Merge one calculated item into the manager (ItemManager/Utils.elm
 * insertCalculatedItems, non-privileged branch), preserving locally-known
 * bids that the (public-channel) payload doesn't carry:
 *   - bids/bookBids: union, incoming entries win per key. Pusher sends only
 *     the highest two bids; the merge keeps the rest.
 *   - winningBid: keep the LOCAL key when it is numerically newer than the
 *     incoming one AND still points at a valid local bid — stale pusher
 *     events must not roll back fresher data.
 */
export function insertCalculatedItem(manager, uuid, calculated) {
  const itemId = itemIdByUuid(manager, uuid);
  if (itemId == null || !calculated) return manager;
  const item = manager.byId[itemId];

  const existingBids = item.calculated?.bids || {};
  const existingBookBids = item.calculated?.bookBids || {};
  const mergedBids = { ...existingBids, ...calculated.bids };

  let winningBid = calculated.winningBid;
  const localWinning = item.calculated?.winningBid;
  if (localWinning != null && calculated.winningBid != null) {
    const localInt = parseInt(localWinning) || 0;
    const incomingInt = parseInt(calculated.winningBid) || 0;
    const localStillValid = isValidBid(mergedBids[localWinning]);
    if (localInt > incomingInt && localStillValid) {
      winningBid = localWinning;
    }
  }

  const mergedCalculated = {
    ...calculated,
    bids: mergedBids,
    bookBids: { ...existingBookBids, ...calculated.bookBids },
    winningBid,
  };

  return {
    ...manager,
    byId: {
      ...manager.byId,
      [itemId]: {
        ...item,
        calculated: mergedCalculated,
        calculatedState: CALC_STATE.SUCCESS,
      },
    },
  };
}

/** Merge several calculated items (uuid-keyed) into the manager. */
export function insertCalculatedItems(manager, entries) {
  return (entries || []).reduce(
    (acc, { uuid, calculated }) => insertCalculatedItem(acc, uuid, calculated),
    manager,
  );
}

/** Mark item ids as loading/failure (ItemManager/Update.elm bookkeeping). */
export function setCalculatedState(manager, itemIds, calculatedState) {
  if (!itemIds || itemIds.length === 0) return manager;
  const byId = { ...manager.byId };
  let changed = false;
  itemIds.forEach((itemId) => {
    const item = byId[itemId];
    if (item) {
      byId[itemId] = { ...item, calculatedState };
      changed = true;
    }
  });
  return changed ? { ...manager, byId } : manager;
}

/**
 * Insert/replace a single bid in an item's calculated bid dict, routed by bid
 * type (ItemManager/Utils.elm updateBidDict): mail bids go to bookBids,
 * everything else to the live bids dict.
 */
export function updateBidDict(manager, itemId, bidKey, bid) {
  const item = manager.byId[itemId];
  if (!item || !item.calculated || !bid) return manager;
  const calculated = item.calculated;
  const isMail = bid.type === 'mail';
  const updatedCalculated = isMail
    ? { ...calculated, bookBids: { ...calculated.bookBids, [bidKey]: bid } }
    : { ...calculated, bids: { ...calculated.bids, [bidKey]: bid } };
  return {
    ...manager,
    byId: {
      ...manager.byId,
      [itemId]: { ...item, calculated: updatedCalculated },
    },
  };
}

/** A bid by item id + bid key, or null (ItemManager/Utils.elm getBid). */
export function getBid(manager, itemId, bidKey) {
  return manager.byId[itemId]?.calculated?.bids?.[bidKey] || null;
}

/**
 * The current item id and the next one, for lazy loading (ItemManager/
 * Utils.elm getCurrentAndNextItemIds — starts one BEFORE the current index
 * and takes 2, so mid-sale reloads also cover the just-closed lot).
 */
export function getCurrentAndNextItemIds(manager, itemId) {
  const index = manager.order.indexOf(itemId);
  if (index === -1) return [itemId];
  const start = index === 0 ? 0 : index - 1;
  return manager.order.slice(start, start + 2);
}

/**
 * The item ids of the static preload window: the given lot plus the
 * following `count - 1` lots, in catalog order (ItemManager/Utils.elm
 * getWindowItemIds). Falls back to just the given id when it is not in
 * the manager (yet).
 */
export function getWindowItemIds(manager, itemId, count) {
  const index = manager.order.indexOf(itemId);
  if (index === -1) return [itemId];
  return manager.order.slice(index, index + count);
}
