// common/domain/bidding.js
//
// Side-effectful bidding domain actions (network calls) extracted from the web
// PlaceBid component so they can be shared with the React Native app. All
// functions return a normalized `{ ok, ... }` result instead of throwing.
//
// SOURCE OF TRUTH: web/src/pages/PlaceBid.js
//   ("A React implementation of the Elm ItemPreLiveSale page")
//   - executePlaceBid()  -> placeBid()        (lines 364-501)
//   - handleDeleteBid()  -> deleteBid()       (lines 519-604)
//   - executeBuyNow()    -> buyNow()          (lines 703-754; PATCH via
//                             DataCache.patchItemsBs, src/services/DataCache.js
//                             lines 1171-1197)
//   - handleCancelBuyNow() -> cancelBuyNow()  (lines 763-825)
//   - handleApproveTerms() -> approveTerms()  (lines 607-665)
//   - needsTermsApproval() -> needsTermsApproval() (lines 181-201, pure part)
//   - credit-limit check   -> credit/terms pure helpers (lines 986-1058)
//
// All requests hit the bid-server at `config.backendUrl` and send the session
// token as the `access-token` header (`config.accessToken`).
//
// `config` here is the app config object (ConfigContext value): it carries at
// least { backendUrl, accessToken, useMockData }.

import fetchData from '../utils/Util';

/**
 * Bid rejection statuses the bid-server can return on POST /api/bids. The
 * source checks `bidData.status.startsWith('rejected')` and special-cases the
 * three below (source lines 419-436). Any other `rejected_*` value maps to
 * REJECTED_OTHER while preserving the raw status string on the result.
 */
export const BID_STATUS = {
  REJECTED_BELOW_RESERVE: 'rejected_below_reserve',
  REJECTED_OUTBID: 'rejected_outbid',
  REJECTED_OVER_CREDIT_LIMIT: 'rejected_over_credit_limit',
  // Sentinel for a rejection whose exact reason is not one of the above.
  REJECTED_OTHER: 'rejected',
  // Non-status outcomes normalized by these helpers:
  ERROR: 'error', // HTTP/network failure (response not ok, or fetch threw)
};

const jsonHeaders = (config) => ({
  'Content-Type': 'application/json',
  'access-token': config.accessToken,
});

// Best-effort extraction of a server-provided error message. Mirrors the
// source: errorData.title || errorData.detail || errorData.message.
async function readErrorMessage(response, fallback = 'Request failed') {
  try {
    const errorData = await response.json();
    return errorData.title || errorData.detail || errorData.message || fallback;
  } catch (parseError) {
    return fallback;
  }
}

/**
 * Place a mail or agent bid.
 * POST {backendUrl}/api/bids
 * Body: { item_uuid, sale_uuid, amount, type }  (source lines 383-397)
 *
 * @param {object} config  App config ({ backendUrl, accessToken, useMockData }).
 * @param {object} args
 * @param {string} args.itemUuid
 * @param {string} args.saleUuid
 * @param {number} args.amount
 * @param {('mail'|'agent')} args.type
 * @returns {Promise<{ok:boolean, bid?:object, status?:string, error?:string}>}
 *   - ok:true  -> { ok, bid, status }        (status is the server's accepted status)
 *   - rejected -> { ok:false, status:'rejected_*', bid, error }
 *   - http/net -> { ok:false, status:'error', error }
 */
export async function placeBid(config, { itemUuid, saleUuid, amount, type }) {
  // Ensure all values are primitive types to avoid circular reference errors
  // (source lines 383-388).
  const requestBody = {
    item_uuid: String(itemUuid || ''),
    sale_uuid: String(saleUuid || ''),
    amount: Number(amount) || 0,
    type: String(type || ''),
  };

  try {
    const response = await fetchData(
      `${config.backendUrl}/api/bids`,
      {
        method: 'POST',
        headers: jsonHeaders(config),
        body: JSON.stringify(requestBody),
      },
      config,
    );

    if (!response.ok) {
      const error = await readErrorMessage(response, 'Bid failed');
      return { ok: false, status: BID_STATUS.ERROR, error };
    }

    const result = await response.json();

    // API returns data as an array, so get the first element (source line 416).
    const bidData = Array.isArray(result.data)
      ? result.data[0]
      : result.data || result;

    // Check for actual rejection statuses (bid not accepted, source line 419).
    if (bidData && typeof bidData.status === 'string' && bidData.status.startsWith('rejected')) {
      return {
        ok: false,
        status: bidData.status, // one of BID_STATUS.REJECTED_* (raw server value)
        bid: bidData,
        error: bidData.status,
      };
    }

    return {
      ok: true,
      bid: bidData,
      status: bidData?.status, // accepted status as returned by the server
    };
  } catch (err) {
    return { ok: false, status: BID_STATUS.ERROR, error: err.message };
  }
}

/**
 * Delete the current user's own bid.
 * DELETE {backendUrl}/api/bids/{bidId}
 * Body: { deleted_author: <userId> }  (source lines 546-557)
 *
 * @param {object} config
 * @param {(string|number)} bidId
 * @param {object} [opts]
 * @param {(string|number)} [opts.deletedAuthor]  Current user id (config.userData.id).
 * @returns {Promise<{ok:boolean, error?:string}>}
 */
export async function deleteBid(config, bidId, { deletedAuthor } = {}) {
  const requestBody = {
    deleted_author: String(deletedAuthor || ''),
  };

  try {
    const response = await fetchData(
      `${config.backendUrl}/api/bids/${bidId}`,
      {
        method: 'DELETE',
        headers: jsonHeaders(config),
        body: JSON.stringify(requestBody),
      },
      config,
    );

    if (!response.ok) {
      const error = await readErrorMessage(response, 'Delete failed');
      return { ok: false, error };
    }

    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * Purchase an item via Buy Now.
 * PATCH {backendUrl}/api/items/{itemId}
 * Body: { buynow: '1' }
 * (source executeBuyNow lines 703-754, which calls DataCache.patchItemsBs;
 *  patchItemsBs is DataCache.js lines 1171-1197.)
 *
 * @param {object} config
 * @param {(string|number)} itemId  The item numeric id (item.id), NOT the uuid.
 * @returns {Promise<{ok:boolean, data?:object, raw?:object, error?:string}>}
 *   On success `data` is the first element of the returned data array (the
 *   updated item), `raw` is the full parsed response.
 */
export async function buyNow(config, itemId) {
  if (!config.backendUrl || !config.accessToken || !itemId) {
    return { ok: false, error: 'Missing required parameters' };
  }

  try {
    const response = await fetchData(
      `${config.backendUrl}/api/items/${itemId}`,
      {
        method: 'PATCH',
        headers: jsonHeaders(config),
        body: JSON.stringify({ buynow: '1' }),
      },
      config,
    );

    if (!response.ok) {
      const error = await readErrorMessage(response, 'Failed to update item');
      return { ok: false, error };
    }

    const raw = await response.json();
    // API returns data in array format, get first element (source lines 729-732).
    const data = raw && raw.data
      ? (Array.isArray(raw.data) ? raw.data[0] : raw.data)
      : undefined;

    return { ok: true, data, raw };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * Cancel a Buy Now purchase.
 * DELETE {backendUrl}/api/bids/{bidId}  with an EMPTY body ('')
 * (source handleCancelBuyNow lines 778-796 — note: empty string body, unlike
 *  the regular deleteBid which sends a JSON deleted_author body.)
 *
 * @param {object} config
 * @param {(string|number)} bidId  The id of the user's own buy-now bid.
 * @returns {Promise<{ok:boolean, error?:string}>}
 */
export async function cancelBuyNow(config, bidId) {
  try {
    const response = await fetchData(
      `${config.backendUrl}/api/bids/${bidId}`,
      {
        method: 'DELETE',
        headers: jsonHeaders(config),
        body: '',
      },
      config,
    );

    if (!response.ok) {
      const error = await readErrorMessage(response, 'Cancel buy now failed');
      return { ok: false, error };
    }

    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/**
 * Approve the sale's terms for a bidder id.
 * PATCH {backendUrl}/api/v1.0/bidder_ids/{bidderId}
 * Body: { term_approval_date: <unix timestamp, seconds> }
 * (source handleApproveTerms lines 607-665.)
 *
 * @param {object} config
 * @param {object} args
 * @param {(string|number)} args.bidderId
 * @returns {Promise<{ok:boolean, termApprovalDate?:number, error?:string}>}
 *   On success returns the unix timestamp written (so the caller can persist it
 *   and update local state, matching setTermApprovalDate in the source).
 */
export async function approveTerms(config, { bidderId }) {
  if (!bidderId) {
    return { ok: false, error: 'Missing bidder id' };
  }

  // Create unix timestamp (seconds) — source line 620.
  const unixTimestamp = Math.floor(Date.now() / 1000);

  try {
    const response = await fetchData(
      `${config.backendUrl}/api/v1.0/bidder_ids/${bidderId}`,
      {
        method: 'PATCH',
        headers: jsonHeaders(config),
        body: JSON.stringify({ term_approval_date: unixTimestamp }),
      },
      config,
    );

    if (!response.ok) {
      const error = await readErrorMessage(response, 'Terms approval failed');
      return { ok: false, error };
    }

    return { ok: true, termApprovalDate: unixTimestamp };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

// ---------------------------------------------------------------------------
// Pure credit / terms gating helpers
//
// These read bidder info (the `data` returned by fetchBidderIds — an array of
// bidder records, or an object with a `.data` array) and are pure: no network,
// no storage. Ported from the credit-limit useEffect (source lines 986-1058).
// ---------------------------------------------------------------------------

/**
 * Extract the array of bidder records from either the raw response
 * ({ data: [...] }) or an already-unwrapped array.
 */
function bidderList(bidderInfo) {
  if (!bidderInfo) return [];
  if (Array.isArray(bidderInfo)) return bidderInfo;
  if (Array.isArray(bidderInfo.data)) return bidderInfo.data;
  return [];
}

/**
 * The website bidder record (bidder_type === 'website') the source keys off
 * (source line 996).
 * @returns {object|null}
 */
export function findWebsiteBidder(bidderInfo) {
  return bidderList(bidderInfo).find((bidder) => bidder.bidder_type === 'website') || null;
}

/**
 * Does the user have a valid credit limit for agent bidding?
 *
 * GATING RULE (source lines 1006-1043):
 *   liveCredit = parseInt(websiteBidder.live_credit) || 0
 *   hasValidCreditLimit = liveCredit !== 0
 * i.e. `live_credit === 0` means NO credit set (invalid); any non-zero value is
 * valid, and `-1` specifically means UNLIMITED. If there is no website bidder
 * record at all, the source treats credit as NOT valid (line 1043).
 *
 * @returns {boolean}
 */
export function hasValidCreditLimit(bidderInfo) {
  const bidder = findWebsiteBidder(bidderInfo);
  if (!bidder) return false; // no website bidder found means no credit set
  const liveCredit = parseInt(bidder.live_credit) || 0;
  return liveCredit !== 0;
}

/**
 * Is the bidder's website account pending approval?
 * (source lines 1000-1004: websiteBidder.user_status == "pending".)
 * @returns {boolean}
 */
export function isBidderPending(bidderInfo) {
  const bidder = findWebsiteBidder(bidderInfo);
  if (!bidder) return false; // source sets pending=false when no website bidder
  return bidder.user_status == 'pending'; // eslint-disable-line eqeqeq
}

/**
 * The bidder id used for terms approval (source line 1039).
 * @returns {(string|number|null)}
 */
export function getBidderId(bidderInfo) {
  const bidder = findWebsiteBidder(bidderInfo);
  return bidder ? bidder.id : null;
}

/**
 * The server-recorded terms approval date (unix seconds) or null
 * (source line 1013).
 * @returns {(number|null)}
 */
export function getTermApprovalDate(bidderInfo) {
  const bidder = findWebsiteBidder(bidderInfo);
  if (!bidder) return null;
  const value = bidder.term_approval_date;
  return value === undefined ? null : value;
}

/**
 * Whether terms approval must be collected before placing a bid.
 * Pure port of needsTermsApproval() (source lines 181-201) with the browser
 * sessionStorage lookup lifted out into an explicit `sessionApproved` arg (the
 * native caller supplies its own persisted flag).
 *
 * Logic:
 *   - if the feature is disabled -> false
 *   - if already approved this session -> false
 *   - otherwise approval is needed iff termApprovalDate === null
 *
 * @param {object} args
 * @param {boolean} args.enabled          config.siteConfig.termApprovalOnBid
 * @param {(number|null)} args.termApprovalDate
 * @param {boolean} [args.sessionApproved=false]
 * @returns {boolean}
 */
export function needsTermsApproval({ enabled, termApprovalDate, sessionApproved = false }) {
  if (!enabled) return false;
  if (sessionApproved) return false;
  return termApprovalDate === null;
}
