import { useCallback, useEffect, useReducer, useRef } from 'react';
import {
  ACTIONS,
  QUEUED,
  SALE_UPDATE_DEFER_MS,
  initialState,
  reducer,
} from '@common/domain/liveSale/reducer';
import { LIVE_SALE_EVENTS, decodePusherEvent } from '@common/domain/liveSale/pusherEvents';
import { getCurrentAndNextItemIds, itemManagerFromLotMap } from '@common/domain/liveSale/items';
import { fetchCalculatedItems, fetchLiveSale } from '@common/services/liveSaleApi';
import { PusherService } from '@common/services/PusherService';

/**
 * One live-sale state machine + sale-channel pusher, shared by every
 * simulated bidder card (lot, ask, going/sold). Per-bidder queued bids
 * live on the card so one spinner does not lock the others.
 */
export default function useSharedSale({ config, saleUuid }) {
  const [state, dispatch] = useReducer(reducer, initialState);
  const stateRef = useRef(state);
  stateRef.current = state;
  const pusherRef = useRef(null);
  const listenersRef = useRef([]);

  const loadSale = useCallback(async () => {
    if (!saleUuid || !config?.backendUrl) {
      return;
    }
    dispatch({ type: ACTIONS.SALE_FETCH_STARTED });
    const res = await fetchLiveSale(config, saleUuid);
    if (!res.ok) {
      dispatch({ type: ACTIONS.HANDLE_FETCHED_SALE_ERR, error: res.error });
      return;
    }
    dispatch({ type: ACTIONS.HANDLE_FETCHED_SALE_OK, sale: res.sale, lotMap: res.lotMap });
    const manager = itemManagerFromLotMap(res.lotMap);
    const ids = getCurrentAndNextItemIds(manager, res.sale.item);
    if (ids.length) {
      dispatch({ type: ACTIONS.CALCULATED_ITEMS_LOADING, itemIds: ids });
      const calc = await fetchCalculatedItems(config, ids, Date.now());
      if (calc.ok) {
        dispatch({ type: ACTIONS.HANDLE_FETCHED_CALCULATED_ITEMS_OK, entries: calc.entries });
      }
    }
  }, [config, saleUuid]);

  useEffect(() => {
    loadSale();
  }, [loadSale]);

  useEffect(() => {
    if (!config?.pusherKey?.key || !saleUuid) {
      return undefined;
    }
    const svc = new PusherService();
    pusherRef.current = svc;
    svc.init({
      key: config.pusherKey.key,
      cluster: config.pusherKey.cluster,
      authEndpoint: `${config.backendUrl}/api/pusher_auth`,
      accessToken: config.accessToken,
    });
    svc.subscribe(saleUuid, null);
    svc.bindChannelEvents(`sale-${saleUuid}`, LIVE_SALE_EVENTS);

    const handlers = LIVE_SALE_EVENTS.map((eventName) => {
      const handler = (data) => {
        const now = Date.now();
        const event = decodePusherEvent(eventName, data, { nowMs: now });
        if (event) {
          dispatch({ type: ACTIONS.PUSHER_EVENT, event, now, ownBidderNumbers: [] });
        }
        listenersRef.current.forEach((fn) => fn(eventName, data, now));
      };
      svc.on(eventName, handler);
      return { eventName, handler };
    });

    return () => {
      handlers.forEach(({ eventName, handler }) => svc.off(eventName, handler));
      svc.disconnect();
      pusherRef.current = null;
    };
  }, [config, saleUuid]);

  useEffect(() => {
    if (state.pendingSaleUpdate) {
      const t = setTimeout(
        () => dispatch({ type: ACTIONS.APPLY_PENDING_SALE_UPDATE }),
        SALE_UPDATE_DEFER_MS,
      );
      return () => clearTimeout(t);
    }
    return undefined;
  }, [state.pendingSaleUpdate]);

  const queuedActive =
    state.queuedRequest.state === QUEUED.QUEUED || state.queuedRequest.state === QUEUED.SENT;
  useEffect(() => {
    if (!queuedActive) {
      return undefined;
    }
    const interval = setInterval(() => {
      dispatch({ type: ACTIONS.CHECK_QUEUED_REQUEST_TIMEOUT, now: Date.now() });
    }, 2000);
    return () => clearInterval(interval);
  }, [queuedActive]);

  const onSharedEvent = useCallback((fn) => {
    listenersRef.current.push(fn);
    return () => {
      listenersRef.current = listenersRef.current.filter((x) => x !== fn);
    };
  }, []);

  return { state, dispatch, reload: loadSale, onSharedEvent };
}
