const useMockData = 0;

// Fallback appConfig when the host app passes none (keeps the old POC identity
// so back-compat callers still resolve against the test serverless).
const DEFAULT_APP_CONFIG = {
  hostname: 'backoffice.ddev.site',
  siteName: 'backoffice',
};

/**
 * Map a hostname (+ optional explicit env) to the serverless base URL.
 * Ported from web getServerlessURL(); the web's `#circuit-setup serverless=
 * "local"` DOM opt-in becomes the explicit `serverlessEnv: 'local'` field.
 */
export function getServerlessURL(hostname, serverlessEnv) {
  if (serverlessEnv === 'local') {
    return configs.ddevLocalServerless.serverless;
  }
  if (serverlessEnv === 'test') {
    return configs.testPantheon.serverless;
  }
  // Site-specific serverless domains win over the environment mapping — and
  // over an explicit `live` env, whose live host for these sites IS their own
  // domain. Explicit `local`/`test` above stay dev escape hatches.
  const ownDomain = ownServerlessDomains.find((entry) =>
    entry.match.test(hostname || ''),
  );
  if (ownDomain) {
    return configs[ownDomain.config].serverless;
  }

  if (serverlessEnv === 'live') {
    return configs.livePantheon.serverless;
  }

  if (hostname === 'localhost' || /ddev\.site/.test(hostname || '')) {
    return configs.ddevLocal.serverless;
  } else if (/dev-[a-z-]+\.circuit\.auction/.test(hostname || '')) {
    return configs.devPantheon.serverless;
  } else if (/test-[a-z-]+\.circuit\.auction/.test(hostname || '')) {
    return configs.testPantheon.serverless;
  }

  // Default to live serverless.
  return configs.livePantheon.serverless;
}

/**
 * Rewrite ddev hostnames to loopback HTTP proxies so a USB-connected phone
 * can reach this machine via `adb reverse` (Android cannot resolve *.ddev.site).
 * Enabled only when appConfig.localDeviceProxy is set.
 */
function applyLocalDeviceProxy(config) {
  const pairs = [
    ['https://circuit-bid.ddev.site:4443', 'http://127.0.0.1:18080'],
    ['https://circuit-bid.ddev.site', 'http://127.0.0.1:18080'],
    ['https://backoffice.ddev.site', 'http://127.0.0.1:18081'],
  ];
  const rewrite = (value) => {
    if (typeof value !== 'string') {
      return value;
    }
    return pairs.reduce((out, [from, to]) => out.split(from).join(to), value);
  };
  const next = {
    ...config,
    backendUrl: rewrite(config.backendUrl),
    backendUrlForBO: rewrite(config.backendUrlForBO),
    backendUrlForSettings: rewrite(config.backendUrlForSettings),
  };
  if (config.siteConfig) {
    next.siteConfig = {
      ...config.siteConfig,
      backoffice_url: rewrite(config.siteConfig.backoffice_url),
      self: rewrite(config.siteConfig.self),
    };
  }
  return next;
}

/**
 * Fetch the per-site runtime config from the serverless get-config service.
 * Memoized like the web version (one resolution per app run).
 */
const getConfigByHostname = (() => {
  let config = null;

  return async (appConfig = DEFAULT_APP_CONFIG) => {
    if (config) {
      return config;
    }

    const hostname = appConfig.hostname || DEFAULT_APP_CONFIG.hostname;
    const siteName = appConfig.siteName || '';

    // jbull host — hardcoded config, no network call (China firewall).
    if (hostname === 'jbull.com' || hostname === 'www.jbull.com') {
      config = {
        ...jbullConfigLive,
        success: true,
        useMockData: useMockData,
      };
      return config;
    }

    const serverlessURL = getServerlessURL(hostname, appConfig.serverlessEnv);
    try {
      const url = `${serverlessURL}get-config?hostname=${encodeURIComponent(
        hostname,
      )}&sitename=${encodeURIComponent(siteName)}`;
      const response = await fetch(url, { method: 'GET' });

      if (response.ok) {
        const fetched = await response.json();
        config = {
          ...fetched,
          success: true,
          useMockData: useMockData,
        };
        if (appConfig.localDeviceProxy) {
          config = applyLocalDeviceProxy(config);
        }
        return config;
      }
      console.error('Failed to fetch configuration:', response.status);
    } catch (error) {
      console.error('Error fetching configuration:', error);
    }

    // Do NOT memoize the failure — a retry (next app start / provider mount)
    // should attempt the fetch again.
    return {
      ...configs.ddevLocal,
      success: false,
      useMockData: useMockData,
    };
  };
})();

export const ConfigContext = createContext(null);

export const ConfigProvider = ({ children, appConfig }) => {
  // Capture the first appConfig value — the app identity is fixed per build,
  // and a stable reference keeps fetchConfig/effects from re-firing if a
  // caller passes an inline object literal.
  const [stableAppConfig] = useState(appConfig);
  const [config, setConfig] = useState({
    siteName: null,
    backendUrl: null,
    success: false,
    useMockData: 0,
    accessToken: null,
    siteData: {},
    userData: {},
    fetchUserData: null,
    setAccessToken: null,
  });
  const [loading, setLoading] = useState(true);

  // Normalize site data the way the web app does (web/src/config/Config.js
  // processSiteData): coerce connected_backoffices to an array and compute
  // backoffice_url_lang (the language-prefixed backoffice base used by
  // sale-search, items-json, catalogs and the account screens).
  const processSiteData = useCallback((rawSiteData) => {
    const siteData = { ...(rawSiteData || {}) };

    if (siteData.connected_backoffices == null) {
      siteData.connected_backoffices = [];
    } else if (!Array.isArray(siteData.connected_backoffices)) {
      siteData.connected_backoffices = [siteData.connected_backoffices];
    }

    if (siteData.languages && siteData.languages.length > 1) {
      const lang = getLanguage();
      const languageForServer = lang === 'zh' ? 'zh-hans' : lang;
      siteData.backoffice_url_lang =
        siteData.backoffice_url + '/' + languageForServer;
    } else {
      siteData.backoffice_url_lang = siteData.backoffice_url;
    }

    return siteData;
  }, []);

  // Fallback for configs that carry no siteConfig: fetch the site record from
  // the bid-server directly (legacy POC path — get-config normally supplies
  // siteConfig, matching the web).
  const fetchSiteData = useCallback(async (configData) => {
    try {
      const response = await fetchData(
        `${configData.backendUrl}/api/sites?name=${configData.siteName}`,
        { mockData: 'api-sites' }
      );

      if (response.ok) {
        const result = await response.json();
        const siteData = processSiteData(result.data[0]);
        setConfig((prevConfig) => ({
          ...prevConfig,
          siteData,
        }));
      } else {
        console.log('Site data response:', response);
        throw new Error('Failed to fetch site data');
      }
    } catch (error) {
      console.error('Error fetching site data:', error);
    }
  }, [processSiteData]);

  const setAccessToken = useCallback(async (token) => {
    if (!token) {
      await AsyncStorage.removeItem('bs_access_token');
    } else {
      await AsyncStorage.setItem('bs_access_token', token);
    }
    setConfig((prevConfig) => ({
      ...prevConfig,
      accessToken: token,
    }));
  }, []);

  const fetchConfig = useCallback(async () => {
    try {
      const configData = await getConfigByHostname(stableAppConfig);
      console.log('Config data:', configData);

      // Like the web: get-config returns the site record as `siteConfig`.
      const siteData = configData.siteConfig
        ? processSiteData(configData.siteConfig)
        : null;

      setConfig((prevConfig) => ({
        ...configData,
        userData: prevConfig?.userData || null,
        siteData: siteData || prevConfig?.siteData || null,
        accessToken: prevConfig?.accessToken,
        fetchUserData: fetchUserData,
        setAccessToken: setAccessToken,
      }));

      // Legacy fallback when get-config carried no siteConfig.
      if (!siteData && configData.success && configData.backendUrl) {
        await fetchSiteData(configData);
      }
    } catch (error) {
      console.error('Error fetching configuration:', error);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stableAppConfig, processSiteData, fetchSiteData, setAccessToken]);

  const fetchUserData = useCallback(async () => {
    try {
      if (config.accessToken && config.backendUrl) {
        // Check if force_bo_refresh flag is set in AsyncStorage
        const forceRefresh = await AsyncStorage.getItem('force_bo_refresh');
        let url = `${config.backendUrl}/api/me`;

        // Append force_bo_refresh parameter if it exists
        if (forceRefresh === '1') {
          url += '?force_bo_refresh=1';
          // Clear the flag after using it
          await AsyncStorage.removeItem('force_bo_refresh');
        }

        // Match web + DataCache: send the session token as the `access-token`
        // header rather than a query param.
        const response = await fetchData(url, {
          mockData: 'api-me',
          headers: { 'access-token': config.accessToken },
        });

        if (response.ok) {
          const userData = await response.json();
          // If no bo token, then take from AsyncStorage
          if (!userData.bo_access_token) {
            userData.bo_access_token = await AsyncStorage.getItem('bo_access_token') || null;
          }
          setConfig((prevConfig) => ({
            ...prevConfig,
            userData: userData,
          }));
        } else {
          console.log('User data response:', response);
          throw new Error('Failed to fetch user data');
        }
      } else {
        console.warn('Access token is empty. Skipping user data fetch.');
      }
    } catch (error) {
      console.error('Error fetching user data:', error);
    }
  }, [config.accessToken, config.backendUrl]);

  useEffect(() => {
    const fetchConfigAsync = async () => {
      const accessToken = await AsyncStorage.getItem('bs_access_token');
      await setAccessToken(accessToken);
      console.log('Fetching config...');
      await fetchConfig();
      setLoading(false);
    };

    fetchConfigAsync();
  }, [fetchConfig, setAccessToken]);

  useEffect(() => {
    if (config.accessToken && config.backendUrl) {
      fetchUserData();
    }
  }, [config.accessToken, config.backendUrl, fetchUserData]);

  // Expose `loading` on the context value and always render children, so a
  // parent (RootNavigator) can show a Splash while config resolves instead
  // of the provider returning null (which would blank the whole tree).
  const memoizedConfig = useMemo(() => ({ ...config, loading }), [config, loading]);

  return (
    <ConfigContext.Provider value={memoizedConfig}>
      {children}
    </ConfigContext.Provider>
  );
};

export function formatCurrencyAmount(amount, currency, fractionDigits = 0) {
  if (amount === null || amount === undefined) {
    return '';
  }

  // Convert amount to number
  const numAmount = Number(amount);

  let formatted;
  const numberFormat = {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
    useGrouping: true
  };

  switch (currency) {
    case 'CHF':
      formatted = `${numAmount.toLocaleString('de-CH', numberFormat)} CHF`;
      break;
    case 'EUR':
      formatted = `${numAmount.toLocaleString('de-DE', numberFormat)} €`;
      break;
    case 'HKD':
      formatted = `${numAmount.toLocaleString('en-US', numberFormat)} HK$`;
      break;
    case 'GBP':
      formatted = `${numAmount.toLocaleString('en-US', numberFormat)} £`;
      break;
    case 'ILS':
      formatted = `${numAmount.toLocaleString('en-US', numberFormat)} ₪`;
      break;
    case 'USD':
      formatted = `$${numAmount.toLocaleString('en-US', numberFormat)}`;
      break;
    default:
      formatted = numAmount.toLocaleString('en-US', numberFormat);
  }
  return formatted;
}