import React, { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { ITEM_STATUS, isWinningUser, getOwnWinningMailBid } from '@common/domain/liveSale/items';
import {
  bidAmountWithIncrements,
  getBidStepAmount,
  getPriceForBidder,
  nextBidAmountForBidder,
  showAmountInCurrency,
} from '@common/domain/liveSale/pricing';
import { QUEUED } from '@common/domain/liveSale/reducer';
import { SALE_STATUS } from '@common/domain/liveSale/saleModel';
import { isBidderPending, hasValidCreditLimit } from '@common/domain/bidding';
import BidButton from './BidButton';
import AlertBanner from './AlertBanner';
import useBidderLive from '../hooks/useBidderLive';

export default function BidderCard({
  bidder,
  config,
  saleUuid,
  sharedState,
  onSharedEvent,
}) {
  const { t: tr } = useTranslation();
  const bidderInfo = useMemo(
    () => [
      {
        id: bidder.bidder_id,
        bidder_number: bidder.paddle,
        bidder_type: 'website',
        live_credit: bidder.live_credit,
        user_status: bidder.user_status,
        term_approval_date: bidder.term_approval_date,
      },
    ],
    [bidder],
  );

  const live = useBidderLive({
    config,
    saleUuid,
    bidderInfo,
    sharedState,
    onSharedEvent,
  });

  const { sale, items } = sharedState;
  const activeItemId = sharedState.saleState === 'success' ? sale.item : null;
  const activeItem = activeItemId != null ? items.byId[activeItemId] || null : null;
  const calculated = activeItem?.calculated || null;
  const effectiveStatus =
    calculated && sharedState.asyncGoingItemStatus && calculated.status === ITEM_STATUS.OPEN
      ? ITEM_STATUS.GOING
      : calculated?.status || null;

  const currency = sharedState.selectedCurrency || sale?.currency;
  const formatAmount = (amount) => showAmountInCurrency(sale, currency, amount);
  const askAmount = calculated
    ? bidAmountWithIncrements(
        nextBidAmountForBidder(calculated, sharedState.clerkHighestQueuedBidData),
        live.increments,
      )
    : null;
  const incrementStep = calculated ? getBidStepAmount(calculated.bidSteps, askAmount) : 0;
  const bidLocked =
    live.queued.state === QUEUED.SENT || live.queued.state === QUEUED.QUEUED;
  const highestBidder = calculated ? isWinningUser(calculated, live.ownBidderNumbers) : false;
  const winningMailBid = calculated
    ? getOwnWinningMailBid(calculated, live.ownBidderNumbers)
    : null;
  const soldAmountText = calculated
    ? formatAmount(
        calculated.currentPrice != null ? calculated.currentPrice : calculated.openingPrice,
      )
    : null;
  const pendingApproval = isBidderPending(bidderInfo);
  const creditOk = hasValidCreditLimit(bidderInfo);
  const liveOpen = sale?.status === SALE_STATUS.LIVE_AUCTION_OPEN;
  const price = calculated
    ? getPriceForBidder(calculated, sharedState.clerkHighestQueuedBidData)
    : null;

  let statusLabel = 'idle';
  if (bidLocked) {
    statusLabel = 'queued';
  } else if (highestBidder) {
    statusLabel = 'winning';
  } else if (live.lastResult?.status) {
    statusLabel = live.lastResult.status;
  }

  return (
    <div className="card">
      <div className="row" style={{ justifyContent: 'space-between', marginBottom: 8 }}>
        <div>
          <div style={{ fontWeight: 700 }}>{bidder.name}</div>
          <div className="muted">{bidder.mail}</div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div className="paddle">#{bidder.paddle}</div>
          <div className="muted">
            <span
              className={`status-dot ${bidLocked ? 'queued' : liveOpen ? 'live' : 'idle'}`}
            />{' '}
            {statusLabel}
          </div>
        </div>
      </div>

      {price && sale ? (
        <div className="muted" style={{ marginBottom: 4 }}>
          Ask {formatAmount(price.amount)}
        </div>
      ) : null}

      <AlertBanner alert={live.alert} formatAmount={sale ? formatAmount : null} />

      {pendingApproval ? (
        <div className="banner error">{tr('placeBid.accountPendingMessage')}</div>
      ) : null}
      {!creditOk ? (
        <div className="banner notice">{tr('liveauctionpage.noCreditLimit')}</div>
      ) : null}

      {liveOpen && !pendingApproval && calculated ? (
        <BidButton
          status={effectiveStatus}
          isHighestBidder={highestBidder}
          amountText={askAmount != null ? formatAmount(askAmount) : ''}
          soldAmountText={soldAmountText}
          maxBidText={winningMailBid ? formatAmount(winningMailBid.amount) : null}
          bidLocked={bidLocked}
          canDecrement={live.increments.length > 0}
          onPlaceBid={() => live.placeBid(activeItemId, askAmount)}
          onIncrement={() => live.increment(incrementStep)}
          onDecrement={live.decrement}
          onPressIn={live.onBidPressIn}
          onPressOut={live.onBidPressOut}
        />
      ) : null}

      {live.lastResult?.error ? (
        <div className="error" style={{ marginTop: 8 }}>
          {live.lastResult.error}
        </div>
      ) : null}
    </div>
  );
}
