import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { QUEUED, QUEUED_REQUEST_TIMEOUT_MS, ALERT } from '@common/domain/liveSale/reducer';
import { decodePusherEvent } from '@common/domain/liveSale/pusherEvents';
import { SALE_STATUS } from '@common/domain/liveSale/saleModel';
import { findWebsiteBidder } from '@common/domain/bidding';
import { placeLiveBid, sendConnectedUserEvent, CONNECTED_USER_EVENT } from '@common/services/liveSaleApi';
import { PusherService } from '@common/services/PusherService';

const emptyQueued = () => ({
  state: QUEUED.NONE,
  taskId: null,
  startTime: null,
  error: null,
});

/**
 * Per-bidder queued-bid + private pusher. Sale/lot state is shared.
 */
export default function useBidderLive({ config, saleUuid, bidderInfo, sharedState, onSharedEvent }) {
  const [queued, setQueued] = useState(emptyQueued);
  const [increments, setIncrements] = useState([]);
  const [alert, setAlert] = useState(null);
  const [lastResult, setLastResult] = useState(null);
  const queuedRef = useRef(queued);
  queuedRef.current = queued;
  const bufferRef = useRef([]);

  const ownBidderNumbers = useMemo(() => {
    const records = Array.isArray(bidderInfo) ? bidderInfo : bidderInfo?.data || [];
    return records.map((r) => parseInt(r.bidder_number, 10)).filter((n) => !Number.isNaN(n));
  }, [bidderInfo]);

  const applyLiveQueue = useCallback((result, now) => {
    if (result.kind === 'placeBidSuccess') {
      setQueued(emptyQueued());
      setAlert({ at: now, type: ALERT.BID_ACCEPTED, amount: result.bid?.amount });
      setLastResult({ ok: true, status: 'accepted', at: now });
      return;
    }
    if (result.kind === 'placeBidFailure') {
      setQueued(emptyQueued());
      setAlert({ at: now, type: ALERT.BID_REJECTED });
      setLastResult({ ok: false, status: 'rejected', error: result.error, at: now });
    }
  }, []);

  useEffect(() => {
    if (!config?.pusherKey?.key || !saleUuid || !config.userData?.uuid) {
      return undefined;
    }
    const svc = new PusherService();
    svc.init({
      key: config.pusherKey.key,
      cluster: config.pusherKey.cluster,
      authEndpoint: `${config.backendUrl}/api/pusher_auth`,
      accessToken: config.accessToken,
    });
    svc.subscribe(saleUuid, config.userData.uuid);
    svc.bindChannelEvents(`private-user-${config.userData.uuid}`, ['livequeue__post_execute']);

    const handler = (data) => {
      const now = Date.now();
      const event = decodePusherEvent('livequeue__post_execute', data, { nowMs: now });
      if (!event || event.type !== 'liveQueuePostExecute') {
        return;
      }
      const q = queuedRef.current;
      if (q.state === QUEUED.QUEUED && q.taskId && event.taskId && q.taskId !== event.taskId) {
        return;
      }
      if (event.result && (event.result.kind === 'placeBidSuccess' || event.result.kind === 'placeBidFailure')) {
        if (q.state !== QUEUED.QUEUED) {
          bufferRef.current.push({ taskId: event.taskId, result: event.result });
          return;
        }
        applyLiveQueue(event.result, now);
      }
    };
    svc.on('livequeue__post_execute', handler);
    return () => {
      svc.off('livequeue__post_execute', handler);
      svc.disconnect();
    };
  }, [config, saleUuid, applyLiveQueue]);

  useEffect(() => {
    if (!onSharedEvent) {
      return undefined;
    }
    return onSharedEvent((eventName, data, now) => {
      if (eventName !== 'livequeue__post_execute') {
        return;
      }
      const event = decodePusherEvent(eventName, data, { nowMs: now });
      if (!event || event.type !== 'liveQueuePostExecute') {
        return;
      }
      const q = queuedRef.current;
      if (q.state === QUEUED.QUEUED && event.taskId && q.taskId === event.taskId) {
        applyLiveQueue(event.result, now);
      }
    });
  }, [onSharedEvent, applyLiveQueue]);

  const queuedActive = queued.state === QUEUED.QUEUED || queued.state === QUEUED.SENT;
  useEffect(() => {
    if (!queuedActive) {
      return undefined;
    }
    const interval = setInterval(() => {
      const q = queuedRef.current;
      if (
        (q.state === QUEUED.QUEUED || q.state === QUEUED.SENT) &&
        q.startTime != null &&
        Date.now() - q.startTime > QUEUED_REQUEST_TIMEOUT_MS
      ) {
        setQueued(emptyQueued());
        setLastResult({ ok: false, status: 'timeout', at: Date.now() });
      }
    }, 2000);
    return () => clearInterval(interval);
  }, [queuedActive]);

  const placeBid = useCallback(
    async (itemId, amount) => {
      const s = sharedState;
      if (queuedRef.current.state === QUEUED.SENT || queuedRef.current.state === QUEUED.QUEUED) {
        return { ok: false, reason: 'in-flight' };
      }
      if (s.saleState !== 'success' || s.sale?.status !== SALE_STATUS.LIVE_AUCTION_OPEN) {
        return { ok: false, reason: 'not-live' };
      }
      const bidder = findWebsiteBidder(bidderInfo);
      const bidderNumber = bidder ? parseInt(bidder.bidder_number, 10) : null;
      if (!bidderNumber) {
        return { ok: false, reason: 'no-bidder-number' };
      }
      const now = Date.now();
      setQueued({ state: QUEUED.SENT, taskId: null, startTime: now, error: null });
      const res = await placeLiveBid(config, { saleUuid, itemId, bidderNumber, amount });
      if (!res.ok) {
        setQueued(emptyQueued());
        setLastResult({ ok: false, status: 'error', error: res.error, at: Date.now() });
        return res;
      }
      const buffered = bufferRef.current.find((entry) => entry.taskId === res.taskId);
      bufferRef.current = bufferRef.current.filter((entry) => entry.taskId !== res.taskId);
      setQueued({
        state: QUEUED.QUEUED,
        taskId: res.taskId,
        startTime: Date.now(),
        error: null,
      });
      if (buffered) {
        applyLiveQueue(buffered.result, Date.now());
      }
      return res;
    },
    [config, saleUuid, bidderInfo, sharedState, applyLiveQueue],
  );

  const increment = useCallback((amount) => {
    setIncrements((stack) => [amount, ...stack]);
  }, []);
  const decrement = useCallback(() => {
    setIncrements((stack) => stack.slice(1));
  }, []);

  const sendPresence = useCallback(
    (event) => {
      if (sharedState.saleState !== 'success' || sharedState.sale?.status !== SALE_STATUS.LIVE_AUCTION_OPEN) {
        return;
      }
      const bidder = findWebsiteBidder(bidderInfo);
      sendConnectedUserEvent(config, {
        event,
        saleUuid,
        bidderNumber: bidder ? bidder.bidder_number : '',
      });
    },
    [config, saleUuid, bidderInfo, sharedState],
  );

  return {
    queued,
    increments,
    alert,
    lastResult,
    ownBidderNumbers,
    placeBid,
    increment,
    decrement,
    onBidPressIn: () => sendPresence(CONNECTED_USER_EVENT.PLACE_BID_MOUSE_ENTER),
    onBidPressOut: () => sendPresence(CONNECTED_USER_EVENT.PLACE_BID_MOUSE_LEAVE),
  };
}
